-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(848, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Sporen, {name}? Ich muss meinem Kollegen in Thunder Bluff ein Gebräu schicken, für das diese Sporen benötigt werden...", completion = "Ah, ja. Das sind wirklich Prachtexemplare. Sehr wirksam.\n\nIch bin ein Verlassener und wir halten unsere Versprechen. Hier ist Eure Belohnung, {name}." }, enUS = { progress = "Do you have the spores, {name}?  There is a concoction I must send to my associate in Thunder Bluff, which requires the spores...", completion = "Ah, yes.  These are good specimens.  Potent.\n\nI am Forsaken, and we honor our contracts.  Here is your reward, {name}." } })
apply(849, { "classic", "forever" }, { deDE = { progress = "Wenn der Flugapparat der Zwerge erst zerstört ist, werde ich die süße Genugtuung der Rache schmecken.", completion = "Das habt Ihr gut gemacht, {name}. Mögt Ihr in Thunder Bluff als Verteidiger des heiligen Tauren-Landes und Champion des verlorenen Stammes verehrt werden." }, enUS = { progress = "Once the dwarven flying machine has been destroyed I will feel the sweet satisfaction of revenge.", completion = "You have done well, {name}! May you be revered in Thunder Bluff as a defender of sacred tauren lands and a champion of the lost tribe." } })
apply(850, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Bringt Ihr mir Baraks Kopf?", completion = "Gut gemacht, {name}. Die Zentauren sind niedere, brutale Kreaturen, aber ein paar von ihnen verfügen doch über genug Verstand und Vorstellungskraft, um sie zu führen. Und das sind die gefährlichsten.\n\nBarak war ein solcher Zentaur. Nur gut, dass er jetzt tot ist." }, enUS = { progress = "Hello, {name}.  Do you have Barak's Head for me?", completion = "Well done, {name}.  The centaur are low, brutish creatures, but a few have the wit and vision to lead.  And those are the most dangerous.\n\nBarak was such a centaur.  It is good that he is dead." } })
apply(851, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Verog gefunden, {name}?", completion = "Sehr gut. Ihr müsst diese Zentauren wirklich aufgescheucht haben - unsere Wachen haben in der Nähe der brackigen Oase Aktivitäten bemerkt, vielleicht wart Ihr das ja.\n\nIhr könnt stolz auf Eure Taten sein, {name}. In Euch steckt viel Mut." }, enUS = { progress = "Did you find Verog, {name}?", completion = "Very good.  You must have really stirred up those centaur -- our guards spotted activity down near the Stagnant Oasis, which was probably you.\n\nYou should be proud of your deed, {name}.  There is much bravery in you." } })
apply(852, { "classic", "forever" }, { deDE = { progress = "Ist Hezrul besiegt, {name}?", completion = "Ich bewundere Euch, {name}. Diese Zentauren sind undiszipliniert und können ihre Wut nicht so konzentrieren wie die Orcs, aber sie sind dennoch unerbittlich wild. Ihr habt Euren Wagemut bewiesen, indem Ihr sie besiegtet." }, enUS = { progress = "Is Hezrul defeated, {name}?", completion = "I commend you, {name}.  These centaur are undisciplined and cannot focus their rage as the orcs can, but they are fierce nonetheless.  In defeating them, your valor is proven." } })
apply(853, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas von Apotheker Helbrim für mich?", completion = "Ah, die Sporen aus dem Brachland, die Helbrim sammeln wollte. Er hat Euch also gebeten, sie auszuliefern? Gut.\n\nUnd da die Emulsion immer noch wirkungsvoll ist, habt Ihr offenbar keine Zeit verloren, sie mir zu bringen. Gut gemacht, {class}." }, enUS = { progress = "You have something from Apothecary Helbrim?", completion = "Ah, the spores from the Barrens that Helbrim was gathering.  He garnered your aid in delivering them?  Good.\n\nAnd the emulsion is still potent, so you must have wasted no time in the delivery.  Well done, {class}." } })
apply(854, { "classic", "forever" }, { deDE = { completion = "Es ist schön zu sehen, dass uns noch mehr unserer Verbündeten von so weit entfernt wie Thunder Bluff zu Hilfe kommen, {race}. Ich heiße Euch erneut willkommen." }, enUS = { completion = "It is good to see that more of our {race} allies have come to assist us from as far away as Thunder Bluff. Again, I welcome you." } })
apply(855, { "classic", "forever" }, { deDE = { progress = "Wie läuft Eure Jagd, {name}?", completion = "Sehr gut gemacht. Ihr habt den überlebenden Zentauren bestimmt eine Heidenangst eingejagt, {name}. Wenn sie klug sind, beruhigen sie sich jetzt und stellen ihre Angriffe ein.\n\nAber ich glaube nicht daran und das ist bedauerlich.\n\nBedauerlich... für sie." }, enUS = { progress = "How goes your hunting, {name}?", completion = "Nicely done.  I'm sure you've struck fear into the surviving centaurs, {name}.  If they have sense, they'll now calm themselves and stop their advances.\n\nBut I don't think they will, and that is unfortunate.\n\nUnfortunate...for them." } })
apply(857, { "classic", "forever" }, { deDE = { progress = "Wo ist die Träne der Monde? Ich brauche sie jetzt! Ich brauche sie!", completion = "Endlich, die Macht gehört wieder mir! Mir!" }, enUS = { progress = "Where is the Tear of the Moons? I need it now! Need I say!", completion = "At last, the power is mine again! Mine I say!" } })
apply(858, { "classic", "forever" }, { deDE = { progress = "Schnell, wir müssen hier weg, bevor jemand misstrauisch wird!", completion = "Ja, das sieht nach dem richtigen Schlüssel aus. Lasst mich nur kurz sehen, wie dieses Ding funktioniert...\n\nHmm... Rotationssteuerung... Damit werden Tempo und Stabilität reguliert... präzise Auslegersteuerung. Seht Euch das nur mal an! Ich fasse es nicht, dass die Venture Company etwas entwickelt hat, das so viel besser ist als unseres. Ich muss das nach Ratchet bringen!" }, enUS = { progress = "Quick, we need to get out of here before someone gets suspicious!", completion = "Yep, this looks like the right key. Let me just make sure I know how to work this thing...\n\nHmm... rotation control... This regulates speed and stability... fine arm movement control. Just look at this! I can't believe the Venture Company could design something this much better than ours. I've got to get this back to Ratchet!" } })
apply(860, { "classic", "forever" }, { deDE = { completion = "Ihr möchtet im Brachland jagen?\n\nIhr habt eifrige und junge Augen. Sie sind noch nicht ermüdet vom Lesen der Fährten Eurer Beute in den trockenen Ebenen dieses Landes.\n\nAber sorgt Euch nicht. Wir werden Euren Körper und Euren Geist stärken. Und wir werden Euch lehren, dass die Jagd nicht nur darin besteht, Eure Beute aufzustöbern und zu töten.\n\nMacht Euch bereit. Eure Reise beginnt. Jetzt." }, enUS = { completion = "You want to hunt in the Barrens?\n\nYour eyes are eager, and young.  They're not yet squinted from tracking your prey across this land's dry plains.\n\nBut worry not. We'll toughen your body and your mind.  And we'll teach you that there is more to hunting than finding and killing your quarry.\n\nPrepare yourself.  Your journey begins.  Now." } })
apply(861, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt. Ihr habt etwas an Euch, das mir viel über Euch verrät. Wollt Ihr etwas von mir?", completion = "Skorn Whitecloud ist ein weiser {race}. Jahr um Jahr ging er auf die Jagd, und obwohl sein Körper alt ist, brennt sein Geist doch umso heller. Es ist uns eine Ehre, ihn bei uns zu haben.\n\nWenn Skorn Euch zu mir geschickt hat, dann müsst auch Ihr vom Geist der Jäger erfüllt sein. Und Ihr habt diese Klauen mitgebracht, die Euer wachsendes Können beweisen.\n\nVielleicht seid Ihr schon bereit, den Pfad zu beschreiten." }, enUS = { progress = "Greetings.  There is an air about you that tells me much.  Do we have business, you and I?", completion = "Skorn Whitecloud is a wise {race}.  He has hunted for years and years, and although his body is old, his spirit burns fiercely.  We are honored to have him with us.\n\nIf Skorn sent you to me, then  you too must have the hunter's spirit.  And to have gathered these claws shows your burgeoning skills.\n\nPerhaps you are ready to walk the path." } })
apply(862, { "classic", "forever" }, { deDE = { progress = "Na, schon genug Grubenratten erwischt, {name}?", completion = "Normalerweise mag ich diese Nagetiere nicht, wenn sie so... abgehangen sind. Ich lasse sie gern ein paar Wochen faulen, bis sich der Geschmack so richtig entwickelt hat. Aber Ihr seht so hungrig aus.\n\nIch werde Euch etwas Grubenratteneintopf zubereiten. Ah, fertig.\n\nBitte sehr!" }, enUS = { progress = "Whack enough dig rats yet, {name}?", completion = "Normally I don't like to eat these rodents when they're so.... so... ripe. Like to let them rot for a few weeks to really bring out the flavor. But you look so hungry.\n\nLet me fix you some Dig Rat Stew. Ah, there we go.\n\nHere you go!" } })
apply(863, { "classic", "forever" }, { deDE = { completion = "Hoffentlich liefert uns dieser Prototyp-Schrotthaufen etwas Brauchbares... mir läuft langsam die Zeit davon! Ich schicke schnellstens ein Bergungsteam zu Wizzlecranks Standort.\n\nOh, hier habt Ihr noch etwas für Eure Bemühungen." }, enUS = { completion = "Hopefully we'll be able to get something of value from the wrecked shredder prototype... my time's running out! I'll dispatch a salvage team to Wizzlecrank's location on the double.\n\nOh, let me give you something for your trouble, too." } })
apply(864, { "classic", "forever" }, { deDE = { progress = "Willkommen. Zumindest willkommen, wenn Ihr mit einem versiegelten Testset zurückkehrt. Anderenfalls werde ich so tun, als hätte ich Eure völlige Unfähigkeit nicht bemerkt, und Euch mit meinem Zorn verschonen, bis Ihr getan habt, womit Ihr beauftragt wurdet, und Eure Aufgabe ausgeführt habt.", completion = "Ich werde die Daten sofort analysieren. Vielleicht stellt sich Keevers Wahnsinn doch noch als mein Genie heraus.\n\nWas Euch angeht... Ihr seid nützlich für mich und ich belohne jene fürstlich, die weiterhin nützlich sind. Nehmt diesen Gegenstand, diese Münze, und als Wichtigstes noch meinen Dank dazu.\n\nSchaut von Zeit zu Zeit mal wieder rein - ich wette, dass unsere Zusammenarbeit an diesem Projekt noch nicht zu Ende ist." }, enUS = { progress = "Welcome back.  At least, welcome back if you have returned with a sealed testing kit.  Otherwise, I will pretend not to notice your utter incompetence and spare my wrath from you until you do as you have been tasked and accomplish my task.", completion = "I will analyze this data immediately.  Perhaps Keever's insanity will prove to be my genius after all.\n\nAs for you...  you are useful to me, and I reward quite well those who remain useful.  Take this item, this coin, and most importantly my thanks along with them.\n\nCheck back with me from time to time - I wager that our working together on this project is not at an end." } })
apply(865, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Hörner, {name}? Diese Dinger werden mir ein Vermögen einbringen!", completion = "Toll, Ihr habt sie! Jetzt muss ich sie nur noch zermahlen und mit etwas Wein vermischen und..." }, enUS = { progress = "Did you get the horns, {name}?  Those things are going to make me a fortune!", completion = "Great, you got them!  Now I just need to ground them down and mix them with some wine, and..." } })
apply(866, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr die Wurzelproben?", completion = "Ja, ja, die sind wirklich gut! Aus diesen Wurzeln werde ich Pflanzen ziehen, die ich dann studieren kann. Ich erhoffe mir, ein paar neue Eigenschaften daran zu finden. Versteckte, wertvolle Eigenschaften...!\n\nUnd keine Sorge - sollte ich etwas finden, seid Ihr der Erste, der es erfährt. Weil ich dann jemanden brauche, der noch mehr sammelt!" }, enUS = { progress = "Hello, {name}.  Did you get those root samples?", completion = "Yes yes, these are very nice!  I will grow specimens from these roots and study them.  I hope to find new properties from them.  Hidden, valuable properties...!\n\nAnd don't worry -- if I do then you'll be the first to know.  Because I'll need someone to gather more!" } })
apply(867, { "classic", "forever" }, { deDE = { progress = "Na, schon genug davon erledigt? Immer schön aufschlitzen und weitere Trophäen sammeln. Ich möchte 8 Krallen der Hexenschwingen haben.", completion = "Oh, die sind hübsch. Wirklich hübsch... Gut gemacht, {name}. Ich freue mich schon so darauf, Euch in Zukunft wieder in Aktion zu sehen." }, enUS = { progress = "Cut up enough of them yet? Keep slicing and taking trophies. I want 8 Witchwing talons.", completion = "Oh, these are nice. Real nice... Good job, {name}. I look forward to seeing more of your work in the future." } })
apply(868, { "classic", "forever" }, { deDE = { progress = "Seid vorsichtig mit den Eiern, die Ihr findet, {name}. Wenn sie zerbrechen, nützen sie mir nichts mehr.", completion = "Ihr macht mich froh, {name}. Die Eier und das Werkzeug. Gut gemacht.\n\nUnd was Eure Belohnung betrifft..." }, enUS = { progress = "Be careful with the eggs you find, {name}. If they break, they be no good to me.", completion = "You please me, {name}. The eggs and the tool. Well done.\n\nAnd for your reward..." } })
apply(869, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Köpfe, {name}?", completion = "Ihr habt uns die Raptoren vom Hals geschafft!\n\nDanke, {name}. Ihr seid ein {class} von hohem Wert." }, enUS = { progress = "Do you have those heads, {name}?", completion = "You got rid of the raptors!\n\nThank you, {name}.  You are a {class} of worth." } })
apply(870, { "classic", "forever" }, { deDE = { completion = "Ihr habt einen Riss in der Erde gefunden, aus dem Gase strömten? Seltsam. Das könnte die Antwort auf unsere Fragen sein, aber das wissen wir nicht sicher.\n\nAber es ist immerhin ein Hinweis. Und ich bin dankbar, dass Ihr ihn gefunden habt." }, enUS = { completion = "You found a fissure in the earth, with gases bubbling from it?  Strange.  This may be an answer to our questions, but we cannot yet be sure.\n\nBut it is a clue.  And I am grateful that you found it." } })
apply(871, { "classic", "forever" }, { deDE = { completion = "Das habt Ihr gut gemacht, {name}. Diese unverschämten Stacheleber werden irgendwann lernen, dass mit der Stärke der Horde nicht zu spaßen ist." }, enUS = { completion = "You have done well, {name}. Those insolent quilboars will finally learn that the might of the Horde is not to be ignored." } })
apply(872, { "classic", "forever" }, { deDE = { progress = "Schneidet dem Anführer den Kopf ab, dann bricht das Chaos aus, {name}. Lernt diese Lektion sorgfältig. Sie wird Euch in der Zukunft helfen.\n\nDie Eber werden ziellos davonstieben und wir können das Brachland zurückerobern.", completion = "Gut gemacht, {name}. Da Kreenig tot ist, werden die Angriffe auf unsere Karawanen merklich nachlassen.\n\nUnser Volk kann sich stolz schätzen, Euch an unserer Seite zu haben." }, enUS = { progress = "Cut off the head of their leader, and chaos ensues, {name}. Learn this lesson well. It will aid you in the future.\n\nThe boars will flounder without direction, and we will be able to take back the Barrens.", completion = "Well done, {name}. With Kreenig's death, there will be a definite decline in the attacks on our caravans.\n\nYour people should be proud to count you among them." } })
apply(873, { "classic", "forever" }, { deDE = { progress = "Fürchtet Euch nicht vor den Gewässern, {race}.", completion = "Ihr seid jetzt eins mit Isha Awak, {name}. Sein Geist ist mit Euch. Er lauert in Euren Augen...\n\nAugen, die eines Tages lernen werden zu sehen." }, enUS = { progress = "Fear not the waters, {race}.", completion = "You now are one with Isha Awak, {name}.  His spirit is with you.  He lurks in your eyes...\n\nEyes that, one day, will learn to see." } })
apply(875, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die 6 Harpyienoffiziersringe schon? Ihnen muss wegen ihrer heimtückischen Angriffe auf die Horde Gerechtigkeit widerfahren.", completion = "Ausgezeichnete Arbeit. Ich glaube, Ihr werdet es in der Horde weit bringen." }, enUS = { progress = "Do you have 6 Harpy Lieutenant Rings yet? Justice must be dealt to them for their vicious attacks on the Horde.", completion = "Excellent work my friend. I think you'll go far within the Horde." } })
apply(876, { "classic", "forever" }, { deDE = { completion = "Ha! Gut gemacht, {name}! Sehr gut gemacht... Ich war mir nicht sicher, ob Ihr der Sache gewachsen seid, aber Ihr habt Euch als ausgezeichneter Halsabschneider erwiesen. Nochmals vielen Dank, dass Ihr uns geholfen habt, die Harpyienepidemie einzudämmen. Hier habt Ihr Eure Belohnung, verwendet sie klug." }, enUS = { completion = "HA! Well done, {name}! Very well done... I wasn't sure you were up to the task, but you've proved yourself quite the cut-throat. Thank you again for helping us suppress the Harpy epidemic. Here is your reward, use it well." } })
apply(877, { "classic", "forever" }, { deDE = { progress = "Wart Ihr in der brackigen Oase? Gab es dort einen Riss unterhalb des Gewässers?", completion = "Eure Entdeckungen sind erstaunlich! Die Samen, die ich Euch gab, waren vertrocknet und tot. Was immer auch unter diesen Oasen schlummert, kann aus dem Nichts Leben entstehen lassen!\n\nWir müssen das noch genauer studieren..." }, enUS = { progress = "Have you been to the Stagnant Oasis?  Was there a fissure beneath its waters?", completion = "Your findings are amazing!  The seeds I gave you were dried, and dead.  Whatever rests under these oases can create life from nothing!\n\nWe must study this more..." } })
apply(878, { "classic", "forever" }, { deDE = { progress = "Mehr Informationen <schnaubt> für die Horde gibt es, wenn Ihr die Weisen der Borstennacken getötet habt, {race}.  Nicht einen Moment früher! Quetschzahn ist kein Narr.", completion = "Ja, ja... viel Freude, da endlich <schnaubt> die Borstennacken den Schmerz meines Stammes kennen, {race}. Das sollte ich fühlen, aber das ist nicht  der Fall.\n\nMan hilft seinen Leuten und sie ehren einen. Quetschzahn hilft seinen Leuten, und was tun sie? Sie drehen ihm den Rücken zu. Sie vergessen ihn und lassen ihn in einem Käfig verrotten!\n\nIch helfe ihnen sogar hinter Gittern und sie schicken niemanden, um mich zu retten!" }, enUS = { progress = "More information <snort> for the Horde when you've killed the Bristleback's wise ones, {race}.  Not a moment earlier! Mangletooth is no fool.", completion = "Yes, yes... filled with joy because finally <snort> the Bristleback know my tribe's pain, {race}. That is how I should feel, but that  is not the case.\n\nYou aid your people and they honor you. Mangletooth aids his people, and what do they do? They turn their backs on him. They forget him and leave him to rot in cage!\n\nI aid them even from locked behind bars and they send no one to save me!" } })
apply(879, { "classic", "forever" }, { deDE = { progress = "Wie läuft Eure Jagd, {race}? \n\nThork glaubt, dass er die Wahrheit darüber kennt, wer die Überfälle auf sein Volk angeführt hat,  aber er wird bald erfahren, wie sehr er sich irrt, wenn Ihr erst Erfolg gehabt habt.\n\nMein Tod ist unabwendbar, aber Ihr habt meinen Feinden große Schmerzen bereitet, sodass Quetschzahn nichts bereut.", completion = "Dann ist es vollbracht. Besser, wenn es so endet, sagt Quetschzahn. <schnaubt> Sie hätten <schnaubt> sicherstellen sollen, dass ich tot bin, als sie mir den Rücken zuwendeten, statt mich <schnaubt> in diesem verlassenen Käfig zu lassen.\n\nJetzt gibt es für Euch nur noch eine Aufgabe zu beenden, {race}." }, enUS = { progress = "How goes your hunt, {race}? \n\nThork thinks he knows the truth about who leads the raids against his people,  but he shall learn how wrong he is if you are successful.\n\nMy death is inescapable, but you have caused great pain to my enemies, so Mangletooth regrets nothing.", completion = "It is done then. Better it ends this way, says Mangletooth. <snort> They should have <snort> made sure I was dead when they turned their backs on me instead of leaving <snort> me here in this forsaken cage.\n\nThere is but one task left for you to finish, {race}." } })
apply(880, { "classic", "forever" }, { deDE = { progress = "Wie läuft Eure Sammelaktion? Habt Ihr die Schalen?", completion = "Danke, {name}. Beim Studieren der Wildtiere eines Gebiets kann man viel über das Gebiet selbst herausfinden. Wir werden sehen, welche Geschichte uns diese Schalen erzählen.\n\nBitte lasst mich Euch für Eure Hilfe danken... und vielleicht habt Ihr ja Verwendung für diese Münzen. Ich zumindest brauche sie nicht." }, enUS = { progress = "How goes your collection?  Did you get the shells?", completion = "Thank you, {name}.  Studying the beasts of an area can tell much about the area itself.  We shall see what tale these shells tell.\n\nPlease accept my gratitude for your aid ... and perhaps you can use these coins.  I find that I do not need them." } })
apply(881, { "classic", "forever" }, { deDE = { progress = "Die große Katze ruft Euch, {name}.", completion = "Ihr habt Echeyakee geschlagen und obwohl seine Tage als Jäger vorbei sind... ist sein Geist mit Euch. Er wird Euch die Kraft zeigen, die im Feingefühl liegt, und welche Ehre Gnade birgt.\n\nEuer Weg ist immer noch lang, {class}. Hoffen wir, dass Ihr ihn gut beschreitet." }, enUS = { progress = "The great cat calls to you, {name}.", completion = "You've beaten Echeyakee, and though his days of hunting are over... his spirit is with you.  He will show you the strength found in subtlety, and the honor in mercy.\n\nYour path is still long, {class}.  Let's hope you stride it well." } })
apply(882, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Ishamuhale schon besiegt, {name}?", completion = "Sein Fangzahn ist nur eine Art Andenken, aber von großer Bedeutung.\n\nIhr tragt Ishamuhales Kraft in Euch, {name}. Mögt Ihr sie mit Mäßigung nutzen. Das ist Eure Bürde.\n\nDas ist Eure Ehre." }, enUS = { progress = "{name}, have you bested Ishamuhale?", completion = "This fang is merely a token, but what it represents is profound.\n\nIshamuhale's strength is in you, {name}.  May you use it with temperance.  That is your burden.\n\nThat is your honor." } })
apply(883, { "classic", "forever" }, { deDE = { progress = "Als ich Euch kommen sah, bemerkte ich eine neue Macht in Eurem Gebaren. Sagt mir - hat sich Euer Geist mit dem großen Lakota'mani vereint?", completion = "Lakota'mani wird in unserer Sprache auch 'Erderschütterer' genannt, denn seine Schritte sind wie der geballte Donner. Er ist jetzt mit Euch und sein Mut und seine Beständigkeit verbinden sich mit Euch. So verbunden gibt es keinen Konflikt, dem Ihr Euch nicht stellen könnt.\n\nSchreitet erhobenen Hauptes, {name}. Schreitet erhobenen Hauptes, Erderschütterer." }, enUS = { progress = "{name}, when you approached I saw a new power in your stride.  Tell me -- has your spirit met with the great Lakota'mani?", completion = "Lakota'mani is called \"Earthshaker\" in our language, and his steps are like gathered thunder.  He is with you now, and his courage mingles with yours.  Together there is no conflict you cannot face.\n\nWalk tall, {name}.  Walk tall, Earthshaker." } })
apply(884, { "classic", "forever" }, { deDE = { progress = "{name}, Eure Augen sind von einer neuen Macht erfüllt! Ihr habt Euch mit dem mächtigen Owatanka vereint, nicht wahr?", completion = "Die Donnerechse Owatanka wird von den Tauren auch 'Blauer Blitz' genannt, denn ihm ist eine Schnelligkeit zu Eigen, über die seine Größe hinwegtäuscht. Man sagt, dass der Blaue Blitz vor langer Zeit von einem Blitz getroffen wurde und die Energie der großen Bestie dank der Himmelswut grenzenlos sei.\n\nMöge seine Energie Euch durchströmen, {name}. Haltet Euren Frieden mit Owatanka." }, enUS = { progress = "{name}, there is a new power behind your eyes!  You have met with the mighty Owatanka, have you not?", completion = "The thunder lizard Owatanka is called \"Bluebolt\" by the tauren, for within him resides a speed that belies his size.  It is said that lightning struck Bluebolt long ago and, fed from the sky's rage, the great beast's energy is without limit.\n\nMay his energy flow through you, {name}.  For you now keep pace with Owatanka." } })
apply(885, { "classic", "forever" }, { deDE = { progress = "Ihr seid von neuer Entschlossenheit erfüllt, {name}. Einer Entschlossenheit, geboren aus Schmerz...\n\nLastet Washte Pawnes Tod auf Euch?", completion = "Der Donnerfalke ist ein seltenes Tier des Brachlandes und sein Tod kann großes Glück oder großes Unheil nach sich ziehen.\n\nWashte Pawne jedoch, auf Taurisch auch 'Geistbeißer' genannt, bedeutet nichts davon... oder beides.\n\nDer Schmerz, den Ihr bei der Jagd auf den Geistbeißer gespürt habt, ist das Schmerzgefühl, das all jene spüren, die unter großen Opfern Großes erreichen. Der Stich, den Ihr gespürt habt, ist der Schmerz des Bedauerns.\n\nIch kann jedoch sehen, dass Ihr ihn überwunden habt. Ihr habt gelernt, dass Bedauern in Weisheit übergeht und dass man durch Schmerz an Kraft gewinnt.\n\nIhr habt viel gelernt, {name}." }, enUS = { progress = "There is new resolve within you, {name}.  A resolve born from pain...\n\nAre you burdened with the death of Washte Pawne?", completion = "The thunderhawk is a rare beast of the Barrens, and its death can portend great fortune, or great doom.\n\nBut Washte Pawne, called \"Spirit Biter\" in Taurahe, can bring neither... or both.\n\nThe pain you felt from hunting Spirit Biter is the pang all feel who make great gains at great costs.  The sting you felt is the pain of regret.\n\nBut I can see you have conquered this.  You have learned that regret turns to wisdom, and that through pain one gains strength.\n\nYou have learned much, {name}." } })
apply(886, { "classic", "forever" }, { deDE = { completion = "Meine Brüder in Thunder Bluff waren weise, Euch herzuschicken, {class}. Denn das Rätsel des Brachlandes ist eines, das ich nicht lösen kann.\n\nLasst uns hoffen, dass wir mit Eurer Hilfe Antworten auf unsere Fragen finden." }, enUS = { completion = "My brethren in Thunder Bluff were wise to send you, young {class}.  For the mystery of the Barrens is one that I alone cannot unravel.\n\nWith your aid, let us hope we can find answers to our questions." } })
apply(887, { "classic", "forever" }, { deDE = { progress = "Ich wage gar nicht daran zu denken, welcher Profit mir durch die Überfälle der Piraten entgeht, und jetzt haben sie auch noch ein Lager direkt vor meiner Haustür aufgeschlagen? Das artet langsam aus, Undermine muss etwas dagegen unternehmen.", completion = "Das habt Ihr gut gemacht. Macht noch ein bisschen so weiter, dann gibt es eine Sache weniger, um die ich mir Sorgen machen muss. Hoffentlich überzeugt es sie davon, woanders ihr Unwesen zu treiben.\n\nIn der Zwischenzeit gäbe es da noch das kleine Problem der mir gestohlenen Waren, die zurückgeholt werden müssen!" }, enUS = { progress = "I don't even want to think about the profits I've lost from pirate raiding, and now they set up camp on my doorstep? It's getting out of hand, Undermine's got to do something about it.", completion = "You did good, kid. A little more work like that, and it'll be one less thing I'll have to worry about. Hopefully they'll be convinced that they should relocate their operation elsewhere.\n\nIn the meantime, there is the small matter of getting back the goods they stole from me!" } })
apply(888, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Sachen gefunden, {name}?", completion = "Was für eine Erleichterung, dass ich all mein Zeug zurückhabe, also danke ich für Eure Hilfe, {name}. Wisst Ihr, ein {race} wie Ihr wäre für meine Unternehmung hier sehr von Nutzen. Solltet Ihr jemals auf Arbeitssuche sein, denkt daran, wie gut Gazlowe für Dienstleistungen zahlt!" }, enUS = { progress = "Did you find my things, {name}?", completion = "It's a relief to get all this stuff back, so thanks for your help, {name}. You know, I could use a {race} like you to help out with my operation here. If you're ever looking for work, don't forget about how well Gazlowe pays for service!" } })
apply(891, { "classic", "forever" }, { deDE = { progress = "Meine Flotte ist in Gefahr, solange Captain Hellstieg und ihre verdammten Kanoniere von der Feste Northwatch aus feuern. Ich möchte, dass auch ihre Soldaten dafür bezahlen. Füllt meine Hände mit Medaillen ihrer Toten, damit ich weiß, dass meine gefallenen Freibeuter gerächt sind.", completion = "Endlich, die Kanonen der rechtschaffenen Allianz wurden zum Schweigen gebracht. Ihr sollt für Eure Hilfe belohnt werden, {name}.\n\nWenden wir uns jetzt der traurigen Aufgabe zu, die Körper der Gefallenen zu bergen..." }, enUS = { progress = "My fleet is in peril with Captain Fairmount and her damned cannoneers blasting away from Northwatch Hold. I want her soldiers to pay as well. Fill my hand with medals from their dead and I will know that vengeance has been given to my fallen privateers.", completion = "Alas, the righteous Alliance guns have been silenced. You shall be rewarded for your aid, {name}.\n\nNow to tend to the grim task of recovering the bodies of the dead...." } })
apply(892, { "classic", "forever" }, { deDE = { progress = "Also, was hat Dizzywig gesagt?", completion = "Keine Chance, was? Dann müssen es wohl die Freibeuter gewesen sein... Dizzywig ist ein aufrichtiger Kerl, er würde mich nicht auf diese Weise hintergehen. Immerhin steht er auf meiner Gehaltsliste.\n\nDann müssen wohl noch ein paar Sachen abgeholt werden, {name}. Was meint Ihr?" }, enUS = { progress = "So, what did Dizzywig have to say?", completion = "No dice, eh? I guess it must have been the Freebooters then... Dizzywig's on the level, I'm sure he wouldn't cheat me like that. After all, he is on the payroll.\n\nLooks like I've got some goods to get back, {name}. What do you say?" } })
apply(893, { "classic", "forever" }, { deDE = { progress = "Ich habe ebenso meine Zweifel daran, dass die jämmerlichen Stacheleber irgendeine Stufe auf dem Gebiet der Schmiedekunst erreichen können, aber der Kriegshäuptling hat es mir befohlen, also werde ich so viel wie möglich über den Grimmhauerstamm in Erfahrung bringen.\n\nIch hatte schon niederere Aufgaben, und ich tue es bereitwillig, wenn es den Orcs hilft.", completion = "Ausgezeichnet, das sind wirklich ausgezeichnete Exemplare.\n\nDie Stacheleber sind doch weiter, als ich erwartet hatte.\n\nHier, {class}, nehmt das und verschwindet. Ich sollte mir diese Waffen näher ansehen. Vielleicht haben wir unsere Feinde unterschätzt und das ist ein Fehler, den wir uns nicht leisten können." }, enUS = { progress = "I, too, have doubts that the pathetic quilboars could attain any level of skill in the area of smithing, but I do as the Warchief commands, and I shall learn what I can about the Razormane tribe.\n\nI have had more menial tasks, and I do so willingly if it aids the orc people.", completion = "Excellent, excellent specimens indeed.\n\nThe quilboar are further along than I had expected.\n\nHere, {class}, take this and get out of my way. I'd better take a closer look at these weapons. We may have underestimated our enemy, and that's the kind of mistake we can't afford to make." } })
apply(895, { "classic", "forever" }, { deDE = { progress = "Was geht ab? Kann ich Euch irgendwie helfen? Habt Ihr Waren zu verschiffen? Oder vielleicht einen Ingenieursjob?", completion = "Ahhhh!!! So eine Art Geschäft also. Wisst Ihr, ich habe die GNADENLOS mal auf offener See gesehen. Furcht erregendes Schiff, oder heißt das Boot... diese Matrosen sind irgendwie anders!\n\nEgal, wie die so übers Wasser gleitet, das war schon sehenswert. Ich bin nur froh, dass ihr berüchtigter Captain keine Gefahr mehr für meine Schiffe ist." }, enUS = { progress = "What's happening? Something I can help you with? Goods to ship, perhaps an engineering job?", completion = "Ahhhh! That sort of business. You know, I saw the Heedless once on the open seas. Fearsome ship, or was that boat... those sailors are so particular!\n\nAnyways, watching her glide across the water was quite a sight to see. I'm glad her infamous captain will trouble my ships no longer." } })
apply(896, { "classic", "forever" }, { deDE = { progress = "Wenn wir nur wüssten, welcher der Minenarbeiter den Smaragd gefunden hat, wäre das der reinste Spaziergang...", completion = "Seht Euch nur an, wie riesig das Ding ist, {name}! Wir sind reich! Mal sehen, wenn man nach dem in Undermine gültigen Kurs für Edelsteine geht, sollte ich Euren Anteil berechnen können - fünfzig Prozent, selbstredend!\n\nAlso, dann sehen wir mal... Ich denke, damit sollten wir quitt sein. Es war mir ein Vergnügen, Geschäfte mit Euch zu machen, {name}." }, enUS = { progress = "If only we knew which one of the miners had found the emerald, it'd be a walk in the park...", completion = "Look at the size of that thing, {name}! We're going to be rich! Let's see, according to the rates I've seen on gems going into Undermine, I should be able to figure out your cut--fifty percent, don't worry!\n\nNow let's see... I think this should do about right. Pleasure doing business with you, {name}." } })
apply(897, { "classic", "forever" }, { deDE = { progress = "Ihr wirkt verstört, {name}. Wie läuft Euer Unterricht im Brachland? Seid Ihr auf etwas Beunruhigendes gestoßen?", completion = "Ich kann Euch nichts über die Natur dieser Bestie sagen, denn ihr Geist hat sie verlassen. Aber wie Ihr schon vermutet habt, gehört sie nicht ins Brachland. Ich fürchte, sie ist Vorbote einer düsteren Zukunft für unser Volk...\n\nIhr solltet Euch bereitmachen und lasst uns hoffen, dass die Zeit das Rätsel dieser Kreatur löst." }, enUS = { progress = "You seemed troubled, {name}.  How go your lessons in the Barrens?  Did you find something that disturbs you?", completion = "I can tell nothing of the nature of this beast, for its spirit has fled.  But as you guessed, it does not belong in the Barrens.  I fear it may herald a grim future for our people...\n\nBut for now, prepare yourself, and let us hope that time unravels the mystery of this creature." } })
apply(898, { "classic", "forever" }, { deDE = { progress = "Ja?", completion = "Wir dachten, Firebough wäre längst tot!\n\nEure Heldentat hat Euch einen Ehrenplatz unter den Thalo'dan-Freibeutern eingebracht, {name}." }, enUS = { progress = "Yes?", completion = "And to think, we thought Firebough was long dead!\n\nYour heroics have earned you a place of honor with the Thalo'dan Privateers, {name}." } })
apply(899, { "classic", "forever" }, { deDE = { progress = "Die Stacheleber werden dafür bezahlen, {name}. Ich schwöre es.", completion = "{class}, Ihr habt meine Aufgabe ernst genommen und dafür danke ich Euch.\n\nMein Verlangen nach Rache ist zwar noch nicht gestillt, aber ich kann immerhin wieder lächeln, da ich sehe, dass auch die Stacheleber leiden mussten." }, enUS = { progress = "The quilboar will pay for this, {name}. I swear it.", completion = "{class}, you take my task seriously, and for that I thank you.\n\nAlthough my desire for revenge remains, I can at least smile seeing that the quilboars have felt pain themselves." } })
apply(900, { "classic", "forever" }, { deDE = { progress = "Blinkende Lampen auf der Steuerkonsole deuten darauf hin, dass die Hauptsteuerventile noch nicht geschlossen wurden.", completion = "Die Lampen erlöschen, sobald die drei Steuerventile geschlossen werden. Grüne Lampen wechseln langsam zu gelb, und der Schalter zur Steuerung des Apparats kann jetzt betätigt werden. Da alle Ventile geschlossen sind, könnt Ihr ihn ausschalten." }, enUS = { progress = "Blinking lights on the control console indicate that the main control valves have not been closed off.", completion = "The lights indicating the three control valves dim as they are shut off. Green lights slowly fade into yellow, and the switch controlling the apparatus is now moveable, with the valves closed, it can be turned off." } })
apply(901, { "classic", "forever" }, { deDE = { progress = "Die Lampen der Konsole leuchten schwach und sämtliche Anzeigen und Skalen stehen auf Null, alles ist im Leerlauf.", completion = "Kaum wird der Schlüssel herumgedreht, öffnet sich die Steuerkonsole. Oben auf der Konsole erlischt eine rote Lampe und das Terminal führt keinen Strom mehr." }, enUS = { progress = "The console lights are dimmed and the gauges and dials all read at their zero positions, everything idling.", completion = "Turning the key in the lock, the control console unlocks. A red light at the top of the console turns off and all power drains from the terminal." } })
apply(902, { "classic", "forever" }, { deDE = { progress = "Ihr seid zurück, {name}! Habt Ihr das Samophlang?", completion = "Das ist... äh... interessant... wirklich. Ich werde es an die Tüftlerverband-Zentrale in Undermine schicken. Ich bin sicher, dass sie dort etwas damit anfangen können, nachdem sie es vorsichtig auseinander genommen und erforscht haben.\n\nAber vielleicht werde ich auch zuerst selbst einen kleinen Blick darauf werfen..." }, enUS = { progress = "Oh, you're back, {name}! Do you have the samophlange?", completion = "This is... er... interesting... yes. I'll have it sent along to the Tinkers' Union headquarters in Undermine. I'm sure after some careful dissection and research, they'll be able to make some sense of it.\n\nBut, perhaps I'll have a little look myself first..." } })
apply(903, { "classic", "forever" }, { deDE = { progress = "Wie läuft Eure Jagd, {name}? Habt Ihr die Streuner gefunden?", completion = "Ah, ich sehe, Ihr wart damit beschäftigt, im Gras zu lauern und Streuner zu jagen. Glaubt Ihr, dass es an der Zeit ist, einem Champion unter ihnen gegenüberzutreten?" }, enUS = { progress = "How goes your hunt, {name}?  Have you found the prowlers?", completion = "Ah, I see you've been busy, lurking in the grasses and hunting prowlers.  Do you think, then, it is time to face a champion among them?" } })
apply(905, { "classic", "forever" }, { deDE = { progress = "Wart Ihr bei den Nestern, {name}?", completion = "Ihr wart also bei den Nestern und habt die Federn Eurer Beute dort abgelegt. Dafür war zweifellos eine gehörige Portion Mut notwendig.\n\nFühlt Ihr Euch ein bisschen stärker, {name}? Denn Ihr seht stärker aus als bei Eurem ersten Besuch hier. Ich glaube, das Brachland zeitigt Erfolg bei Euch." }, enUS = { progress = "Have you been to the nests, {name}?", completion = "So you've been to the nests and placed the feathers of your prey within them.  That took a fair portion of courage, no doubt about it.\n\nDo you feel a little tougher, {name}?  Because you look tougher now then when you first came here.  I guess the Barrens is doing its job." } })
apply(906, { "classic", "forever" }, { deDE = { progress = "Ja, was gibt's?", completion = "Ihr habt den Anführer der Grimmhauer gefunden und eigenhändig getötet, {name}? Erstaunlich.\n\nMir fehlen die Worte, aber das bedeutet nicht, dass ich nicht dankbar bin. Die Leute von Crossroads sollten Respekt vor Eurer Kraft haben.\n\nIch muss gestehen, dass ich dachte, der Anführer all dieser Überfälle auf unsere Nachschublinien wäre ebenfalls ein Stacheleber. Nochmals danke, {name}." }, enUS = { progress = "Yes, what is it?", completion = "You found the Razormane leader and killed him yourself, {name}? Amazing.\n\nI am without words, but that does not mean I am without thanks. The people of the Crossroads would do well to respect your strength.\n\nI must admit, I thought the leader of these raids on our supply lines was another quilboar. Thank you again, {name}." } })
apply(907, { "classic", "forever" }, { deDE = { progress = "Sind die Donnerechsen bezwungen, {name}?", completion = "Es ist gut, Euch mit dem Beweis Eures Sieges zurückkehren zu sehen. Und es ist schön zu wissen, dass Ihr es geschafft habt, Eure Knochen dabei nicht zu brechen." }, enUS = { progress = "Are the thunder lizards defeated, {name}?", completion = "It is good to see you return with proof of victory.  And it is good to know you have done so with your bones unbroken." } })
apply(913, { "classic", "forever" }, { deDE = { progress = "Ist es vollbracht? Habt Ihr den Donnerfalken getötet?", completion = "Ihr solltet, ebenso wie der Donnerfalke, stolz sein. Ihr habt jeden Feind besiegt, gegen den wir Euch geschickt haben, und Ihr habt es mit Stärke, Mut und Ehre geschafft.\n\nAber Euer Weg ist noch nicht zu Ende, {name}. Ihr werdet nämlich herausfinden, dass wahre Jäger auf ewig streben, auf ewig mit dem gleichen Stolz, den Ihr mir gezeigt habt, ihren Weg gehen.\n\nNun ist es an der Zeit, nach vorn zu blicken." }, enUS = { progress = "Is it done? Have you slain the thunderhawk?", completion = "You, like the thunderhawk, should be proud.  You have bested every foe we set you before, and have done so with strength, courage and honor.\n\nBut your path, {name}, continues.  In fact, you will find that true hunters forever strive, forever walk their path with the same pride you have shown me.\n\nNow, it is time to move on." } })
apply(914, { "classic", "forever" }, { deDE = { progress = "Mich verfolgen die Erinnerungen an meine Alpträume, {name}. Habt Ihr die Anführer der Druiden des Giftzahns besiegt und ihre Edelsteine in Euren Besitz gebracht?", completion = "Ihr habt es geschafft, {name}. Ihr habt die Anführer der Druiden des Giftzahns getötet. Jetzt werden meine Träume nicht mehr von ihren Fratzen heimgesucht und Ihr habt uns geholfen, das Brachland vor einer schrecklichen Zukunft zu bewahren.\n\nIch danke Euch, {name}. Ich danke Euch im Namen der Druiden von Thunder Bluff, des ganzen Landes und auch in meinem eigenen Namen." }, enUS = { progress = "Memories of my nightmares haunt me, {name}.  Have you defeated the leaders of the fang and acquired their gems?", completion = "You have done it, {name}.  You killed the leaders of the Druids of the Fang.  My dreams are now free of their wicked faces, and you have helped save the Barrens from a cursed future.\n\nI thank you, {name}.  I thank you for myself, for the druids of Thunder Bluff, and for the land." } })
apply(916, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Giftbeutel, {name}?", completion = "Danke, {name}. Sobald ich wieder in Darnassus bin, werde ich das Gift dieser Drüsenbeutel mit dem Gift anderer Spinnen vergleichen. Ich glaube, dass er Eigenschaften besitzt, die etwas mit dem kürzlichen Wachstumsschub unseres neuen Weltbaums zu tun haben." }, enUS = { progress = "Did you gather the venom sacs, {name}?", completion = "Thank you, {name}.  When I return to Darnassus I will compare the venom within these sacs with the venom of other spiders.  It is my belief that it will have properties linked to the recent growth of our new world tree." } })
apply(917, { "classic", "forever" }, { deDE = { progress = "Wart Ihr in der Schattenweberhöhle, {name}? Habt Ihr ein Spinnen-Ei gefunden?", completion = "Ah, sehr gut. Ich lasse dieses Ei und das Gift nach Darnassus bringen und kehre nach dort zurück, sobald ich meine Studien hier abgeschlossen habe. Ich rechne fest damit, anhand dieser Exemplare eine Menge herauszufinden, {name}. Ihr wart mir eine große Hilfe." }, enUS = { progress = "Have you been inside the Shadowthread Cave, {name}?  Did you find a spider egg?", completion = "Ah, very good.  I will have this egg and the venom transported to Darnassus, then return there when my studies are done here.  I expect to find out a great deal from these specimens, {name}.  You have been a great help to me." } })
apply(918, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Samen? Ich kann es kaum erwarten, sie einzupflanzen.", completion = "Ihr habt sie. Das ist gut!\n\nIch werde diese Samen in einer speziell vorbereiteten Erde einpflanzen. Ich glaube, aus den Samen werden Bäumlinge wachsen, die viel sanftmütiger sind. Vielleicht könnt Ihr Euch später das Ergebnis ansehen!" }, enUS = { progress = "Do you have the seeds?  I am eager to plant them.", completion = "You got them.  This is good!\n\nI will plant these seeds in special soil I have prepared.  I believe the seeds will sprout into timberlings who are much more docile.  Perhaps later you can see the results!" } })
apply(919, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr in der Nähe der Seen Schösslinge gefunden?", completion = "Sind das viele! Ich fürchte, sie verbreiten sich gefährlich schnell. Hoffentlich kann ich den Grund dafür finden, warum sie so besudelt sind.\n\nDanke für Eure Hilfe, {name}. Dank Euch ist das Land wieder viel sauberer." }, enUS = { progress = "Hello, {name}.  Have you found any sprouts near the waters?", completion = "That's a lot!  I'm afraid they're spreading at a dangerous rate.  I hope I can solve the riddle of what is tainting them.\n\nThank you for your help, {name}.  The land is a cleaner place from your efforts." } })
apply(920, { "classic", "forever" }, { deDE = { completion = "Ah, {name}. Ich hatte gehofft, Ihr würdet meiner Einladung bald Folge leisten. Ich habe eine wichtige Aufgabe für Euch." }, enUS = { completion = "Ah, {name}. I was hoping you'd be prompt in answering my summons. I have an important task that I would like you to perform." } })
apply(921, { "classic", "forever" }, { deDE = { progress = "Die Mondbrunnen enthalten das Wasser des Brunnens der Ewigkeit, die uralte Quelle der Magie, die so viel Schrecken über unsere Welt gebracht hat.\n\nDie Druiden nutzen ihre Eigenschaften und die Schildwachen verehren die Brunnen als Schreine der Elune, doch ist Zauberei allen gleichermaßen verboten.", completion = "Jetzt kennt Ihr also den ersten Teil der Geschichte um die Auswirkungen der Schlacht am Berg Hyjal. Es gibt noch so viel mehr zu erzählen, und die Aufgabe, die Ihr hier begonnen habt, wird Euch den Rest Eurer Reise durch Teldrassil und nach Darnassus begleiten." }, enUS = { progress = "The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.\n\nThe druids take advantage of its properties, and the Sentinels revere the wells as shrines to Elune, but sorcery is forbidden to all.", completion = "So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more to be told and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus." } })
apply(922, { "classic", "forever" }, { deDE = { progress = "Hallo...\n\nKann ich Euch irgendwie helfen?", completion = "Ah, ein Bäumlingssamenkorn. Ich wollte schon immer eines davon haben, um Denalan bei seinen Studien zu unterstützen.\n\nLeider habe ich jedoch herausgefunden, dass viele der Bäumlinge eine Schädigung aufweisen und dass auch deren Samenkörner mit dieser Besudelung behaftet sind. Es ist mir nicht möglich, dies zu beheben.\n\nDenalan hat einen grünen Daumen mit Pflanzen. Er könnte ein Heilmittel für künftige Bäumlinge finden. Vielleicht ist er ihre einzige Hoffnung." }, enUS = { progress = "Hello...\n\nAnd how may I help you?", completion = "Ah, a timberling seed?  I wanted to try growing one of these to help Denalan with his studies.\n\nBut I'm afraid I've discovered that a corruption has grown in many of the timberlings, and seeds from such creatures carry their parent's taint.  They are beyond my talents to repair.\n\nDenalan is very skilled with things that grow.  He may find a cure for future timberlings.  He may be their only hope." } })
apply(923, { "classic", "forever" }, { deDE = { progress = "Wart Ihr schon am Wellspringsee, {name}? Habt Ihr dort Bäumlinge gejagt?", completion = "Gut gemacht! Diese Tumore sind ein Symptom der Bäumlingskrankheit. Sie sind mit einem Gift gefüllt, von dem wir unser neues Land säubern müssen.\n\nIch werde diese Tumore entsorgen. Danke, {name}." }, enUS = { progress = "Have you been to Wellspring Lake, {name}?  Have you been hunting the timberlings there?", completion = "Well done!  These tumors are the symptom of the timberling's disease.  They are filled with a poison that we must cleanse from our new land.\n\nI will dispose of these tumors.  Thank you, {name}." } })
apply(924, { "classic", "forever" }, { deDE = { progress = "Die Dämonensaat existiert immer noch. Ich spüre ihre Macht...", completion = "Eure Aufgabe ist vollbracht. Ihr habt die Dämonensaat vernichtet, wie Neeru Euch geheißen hat. Aber das ist noch nicht das Ende...\n\nDie Vernichtung der Dämonensaat hat Wellen der Macht durch den Äther geschickt, Wellen unglaublicher Stärke. Ich habe sie gespürt und ich bin sicher, dass andere Wesen sie ebenfalls spürten. Andere, die sich fragen werden, warum man ihr Spielzeug zerbrochen hat...\n\nDoch was die Zukunft auch bringen mag, ich habe etwas für Euch. Neeru schickt es, sozusagen als Entlohnung. Und er bat mich, Euch zu danken.\n\nAlso - danke." }, enUS = { progress = "The Demon Seed still exists.  I can sense its power...", completion = "Your task is complete.  You have destroyed the Demon Seed as Neeru bid.  But this is not the end...\n\nThe destruction of the Demon Seed sent waves of power through the ether, waves of staggering force.  I felt them, and I am sure other beings did as well.  Others who will wonder why their toy was broken...\n\nBut regardless of future troubles, I have something for you.  Neeru sent it as payment.  And he bid me thank you.\n\nSo, thank you." } })
apply(927, { "classic", "forever" }, { deDE = { progress = "{name}! Habt Ihr etwas für mich?", completion = "Was ist das denn? Ein Bäumlingsherz??? Es ist mit widerlichem Moos bedeckt!\n\nDanke, dass Ihr es mir gebracht habt, {name}. Ich werde das Herz untersuchen, und wenn ich Glück habe, finde ich heraus, was dies für eine Art Moos ist." }, enUS = { progress = "{name}!  You have something for me?", completion = "...What is this?  A timberling heart??  It's covered with a foul moss!\n\nThank you for bringing this to me, {name}.  I will examine the heart and, if fortune shines, determine the nature of the moss about it." } })
apply(928, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {class}. Wem verdanke ich die Ehre Eures Besuchs?", completion = "Ah, ich verstehe. Tenaron schickt Euch. Nun denn, mir scheint, wir haben viel zu besprechen, viel zu tun und nur wenig Zeit dafür.\n\nWir sollten jetzt besser gleich beginnen." }, enUS = { progress = "Greetings, {class}. For what purpose do I owe the pleasure of our meeting?", completion = "Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do, and little time to do it in.\n\nI think we'd best get started." } })
apply(929, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr Eure Aufgabe erledigt?", completion = "Nach der Schlacht am Berg Hyjal waren wir wie verloren. Nordrassil lag unter einer Rauchwolke der Feuer, die darin loderten, und unsere Unsterblichkeit - die Essenz unseres Seins! - war dahin.\n\nIn dieser schwierigen Zeit wurde der Verräter aus seinem Gefängnis befreit und Shan'do Stormrage verschwand spurlos. Das war eine böse Zeit für uns alle." }, enUS = { progress = "Hello again, {name}. Have you completed your task?", completion = "After the Battle of Mount Hyjal, we were without direction. Nordrassil smoked from the fire it unleashed, and our immortality--the very essence of our beings!--was lost.\n\nIt was in this trying time that the Betrayer was freed from his prison, and Shan'do Stormrage disappeared. A dark time for all." } })
apply(930, { "classic", "forever" }, { deDE = { progress = "{name}, Ihr seht aus, als wolltet Ihr mir etwas sagen. Habt Ihr Neuigkeiten bezüglich der Bäumlinge?", completion = "Ihr habt das in Teldrassil gefunden? Interessant... eine exotische Frucht. Vielleicht sind ihre Samen von weither hierher gelangt. Vielleicht sogar aus Azeroth! Irgend etwas ist mit dieser Frucht... sie scheint sich auf sehr seltsame Art dem Erdboden Teldrassils angepasst zu haben.\n\nDanke, {name}. Wenn Ihr mich jetzt bitte entschuldigen wollt, ich muss das hier näher untersuchen..." }, enUS = { progress = "{name}, you look like you have something to tell me.  Do you have news concerning the timberlings?", completion = "You found this on Teldrassil?  Intriguing... this fruit is exotic.  Perhaps its seeds were brought here from far off.  Perhaps even as far as Azeroth!  And there's something about this fruit... it seems to have reacted very strangely with the soil of Teldrassil.\n\nThank you, {name}.  Now if you'll excuse me, I must study this further..." } })
apply(931, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas für mich?", completion = "Wo habt Ihr das her? So eine Pflanze habe ich seit meiner Exkursion in die Sümpfe des Elends nicht mehr gesehen... das ist Jahrzehnte her! Wie erstaunlich, dass ein Exemplar es bis nach Teldrassil geschafft hat. Und wie hochgewachsen sie ist!\n\nDanke, {name}. Vergebt mir, dass ich so kurz angebunden bin, aber ich würde zu gern etwas mit diesem Wedel testen..." }, enUS = { progress = "You have something for me?", completion = "Where did you get this?  I haven't seen a plant like this since a sojourn I made to the Swamp of Sorrows... decades ago!  It's amazing that a specimen made its way to Teldrassil.  And it's grown to such a size!\n\nThank you, {name}.  Forgive my shortness of words, but there is a test I would like to perform on this frond..." } })
apply(932, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Lord Melenas schon getötet? Es ist wichtig, dass man ihn schnell und stillschweigend beseitigt, {name}. Solange er lebt, wird er uns allen Ungemach bereiten.", completion = "Da Lord Melenas jetzt endlich zur Strecke gebracht ist, kann ich mich anderen Dingen zuwenden. Danke, {name}." }, enUS = { progress = "Did you kill Lord Melenas yet? It is vital that he be taken care of quickly and quietly, {name}. His continued existence is an embarrassment to us all.", completion = "With Lord Melenas laid to rest I can finally move on to other matters. Thank you, {name}." } })
apply(933, { "classic", "forever" }, { deDE = { progress = "Zunächst schenkte man den Berichten wahnsinnig gewordener Furbolgs keinerlei Beachtung. Wer hätte gedacht, dass sich diese sonst so friedliebenden Bärmenschen einmal in hirnlose Furien verwandeln würden? Es gibt jedoch noch ein weiteres Problem, das uns hier in unserer neuen Heimat plagt.", completion = "Shan'do Stormrage tauchte nie wieder auf und die Druiden waren in heller Aufregung. Bis zum heutigen Tag weiß niemand, was aus ihm geworden ist. Da Malfurion unauffindbar war, übernahm der Erzdruide Fandral Staghelm die Führung der Druiden und überzeugte den Kreis der Urtume in Dunkelküste davon, dass es an der Zeit wäre, unser Volk neu zu organisieren und dass es ebenfalls an der Zeit wäre, unsere Unsterblichkeit wiederzuerlangen.\n\nMit Zustimmung des Kreises pflanzten Staghelm und die mächtigsten der Druiden Teldrassil, den neuen Weltbaum." }, enUS = { progress = "At first the reports of crazed furbolg attacks were dismissed. Who could have thought that the peace-loving bear-men would turn to mindless rage? Yet another of the problems that plagues us here in our new home.", completion = "Shan'do Stormrage never returned, and the druids were in disarray, and to this day we still do not know what became of him. With Malfurion missing, Arch Druid Fandral Staghelm took over the leadership of the druids, convincing the Circle of Ancients in Darkshore that it was time for our people to rebuild, and that it was time for our people to regain their immortality.\n\nWith the approval of the Circle, Staghelm and the most powerful druids grew Teldrassil, the new World Tree." } })
apply(935, { "classic", "forever" }, { deDE = { progress = "Ich weiß, dass ich Euch nicht zu mir gebeten habe, deshalb frage ich mich, was Euch wohl zu mir führen mag, um mit mir zu sprechen.\n\nWas immer es auch sein mag, fasst Euch kurz.", completion = "Ah ja, das Wasser, um das ich gebeten habe. Tenaron und Corithras haben sich mit der Lieferung wirklich Zeit gelassen... vielleicht haben sie sich nicht gerade den zuverlässigsten Boten ausgesucht... hmmm.\n\nNun denn, jetzt kann ich endlich wieder an meine Arbeit gehen. Das Gewicht von Teldrassils Problemen lastet auf meinen Schultern. Ein Joch, dessen ich mich liebend gern so bald wie möglich entledigen möchte.\n\nNehmt das, Ihr werdet es bestimmt irgendwie gebrauchen können." }, enUS = { progress = "I know that I did not summon you, so I cannot help but wonder why it is you have come to speak with me.\n\nWhatever it is, please make it quick.", completion = "Ah yes, the water I had requested. Tenaron and Corithras certainly took their time in having it delivered... perhaps not choosing the most reliable of messengers... hmm.\n\nNonetheless, I can finally get back to my work then. The weight of Teldrassil's problems fall upon my shoulders. A yoke I would wish to soon be rid of.\n\nTake this, you may find some use for it." } })
apply(936, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}; ich freue mich, dass Ihr daran interessiert seid, an unseren Forschungen teilzunehmen. Es gibt viel zu tun und ich würde Euch einen schlechten Dienst erweisen, wenn ich Euch sagen würde, dass die Arbeit, die dies mit sich bringt, ungefährlich sei. Hoffentlich erschreckt Euch das nicht ... aber so, wie Ihr ausseht, würde ich sagen, dass Ihr schon früher der Gefahr ins Auge geblickt habt." }, enUS = { completion = "Greetings, {class}; I am glad you are interested in assisting our research.  There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous.  Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before." } })
apply(937, { "classic", "forever" }, { deDE = { progress = "Ihre scharfen Krallen und spitzen Schnäbel könnten Eure Fähigkeiten auf eine harte Probe stellen, {name}, aber ich vertraue darauf, dass Ihr bei dieser Aufgabe nicht versagt.", completion = "Ich bin beeindruckt, was Ihr in so kurzer Zeit alles bewerkstelligt habt, {name}. Ich würde Euch am liebsten bitten, hier zu bleiben und mir bei meinen Pflichten zu helfen... aber tief in meinem Herzen weiß ich, dass größere Aufgaben auf Euch warten.\n\nMir ist aufgefallen, dass der Orakelbaum einen Teil seiner Rinde abgestoßen hat. Zweifellos hat er eine Aufgabe, die er erledigt haben möchte. Ihr solltet mit ihm sprechen." }, enUS = { progress = "Their slashing talons and piercing beaks may prove a difficult match for your own abilities, {name}, but I have faith that you will not fail in this task.", completion = "I am impressed by what you have accomplished here in so short a time, {name}. Would that I could ask you to remain here to assist me with my duties... but I know in my heart that greater tasks lie ahead for you.\n\nI have noticed the Oracle Tree has just shed a piece of its bark. No doubt it has a task that it wishes completed. You should speak with it." } })
apply(938, { "classic", "forever" }, { deDE = { completion = "Oh, danke, {name}! Ich fürchtete schon, dass ich Nebel nie wiedersehen würde. Ich sah sie tot und würde nie wieder mit meiner treuen Begleiterin zusammensein. Ich schulde Euch mehr als Ihr Euch vorstellen könnt und werde Euch auf ewig dankbar sein." }, enUS = { completion = "Oh, thank you, {name}! I feared I would never see Mist again, knowing only her death in my heart, never to be united with my faithful companion. I owe you more than you can know, and you have my eternal gratitude." } })
apply(939, { "classic", "forever" }, { deDE = { progress = "Was ist, {class}? Ihr seht besorgt aus.", completion = "Ich spüre das Leiden der Uralten, {name}...\n\nEs ist nahezu unerträglich, diese Gegenstände in der Hand zu halten..." }, enUS = { progress = "What is it, {class}? You look concerned.", completion = "I sense the suffering of ancient ones, {name}...\n\nHolding these items is almost unbearable..." } })
apply(940, { "classic", "forever" }, { deDE = { progress = "Hmm... Der Geist des Waldes ist stark in Euch, {class}. Was wollt Ihr vom Erzdruiden der Kaldorei?", completion = "Ich habe mich schon gewundert, warum ich so lange nichts mehr vom Orakelbaum gehört hatte... Es scheint, als würden manche Probleme kleiner, während andere wiederum stetig größer werden.\n\nIch fürchte, meine Arbeit an Teldrassil wird nie ein Ende finden und wir werden unsere Unsterblichkeit nie wiedererlangen.\n\nNichtsdestotrotz habt Ihr die Aufgabe des Orakelbaums trefflich erfüllt und sollt für Euren Fleiß belohnt werden." }, enUS = { progress = "Hmm... You come with the spirit of the forest strongly within you, {class}. What business do you have with the Arch Druid of the Kaldorei?", completion = "I wondered why the Oracle Tree had not communicated with me for so long... It seems that some problems are lessened while others grow to greater concerns.\n\nI fear my work on Teldrassil shall never be completed, and our immortality never restored.\n\nNonetheless, you have done the Oracle Tree's task well, and should be rewarded for your diligence." } })
apply(941, { "classic", "forever" }, { deDE = { progress = "Der Blumentopf ist mit speziell von Denalan vorbereiteter Krume gefüllt.", completion = "Ihr setzt das Herz in den Blumentopf ein, und es beginnt sich im Handumdrehen selbst einzugraben!\n\nNach ein paar Sekunden windet es sich wieder heraus und ist gesäubert. Es pulsiert leicht und bedeutet Euch, es in die Hand zu nehmen." }, enUS = { progress = "This planter is filled with soil, specially prepared by Denalan.", completion = "You place the heart within the planter, and it quickly digs itself in!\n\nA few seconds later it wriggles back out, cleansed.  It pulses slightly... beckoning for you to take it." } })
apply(942, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr da, Freund?", completion = "Oha! Ihr sagt, das da stammt aus dem weit entfernten Land Kalimdor?\n\nErstaunlich! Einfach erstaunlich!" }, enUS = { progress = "What ya got there, friend?", completion = "Oh my! You say this came from the distant lands of Kalimdor?\n\nAmazing! Simply amazing!" } })
apply(943, { "classic", "forever" }, { deDE = { progress = "Mit dem Stein von Relu kann ich nicht nur die verborgenen Geheimnisse meines Fossils, sondern auch die von Remtravels Fossil aus Dunkelküste enthüllen, {name}.", completion = "Sehr eindrucksvoll, {name}!\n\nLasst uns jetzt sehen, ob ich mit Hilfe des Steins die Macht des Fossils entschlüsseln kann." }, enUS = { progress = "With the Stone of Relu I will be able to release the hidden secrets of my fossil as well as Remtravel's fossil from Darkshore, {name}.", completion = "Most excellent, {name}!\n\nNow to see if I can use the stone to decipher the powers of the fossils." } })
apply(944, { "classic", "forever" }, { deDE = { progress = "Die Meistergleve, {name}.\n\nBegebt Euch dorthin und sprecht dann noch mal mit mir.", completion = "Der Klan der Twilight-Hammer ist bei der Meistergleve?\n\nDas ist schlecht.\n\nDer alte Lord, der damals bei der Gleve gepfählt wurde, ist schon lange tot, aber das bedeutet nicht, dass nicht noch immer Teile seiner Macht dort verblieben sind.\n\nDer Klan der Twilight-Hammer muss auf diese Macht aus sein." }, enUS = { progress = "The Master's Glaive, {name}.\n\nGo there, then speak with me again.", completion = "The Twilight's Hammer is at the Master's Glaive?\n\nUnfortunate.\n\nThe old lord impaled by the glaive is long dead, but that does not mean slivers of his power do not still remain.\n\nThe Twilight's Hammer must be seeking this power." } })
apply(945, { "classic", "forever" }, { deDE = { completion = "Wo war meine Schwester??? Therylune ist es egal, ob sie sich schmutzig macht, aber jetzt übertreibt sie! Es ist eine ganz schöne Strecke bis dahin und die Meistergleve ist ein zweifelhafter Ort...\n\nTrotzdem vielen Dank, {name}. Es war sehr freundlich von Euch, mich wissen zu lassen, dass es ihr gut geht." }, enUS = { completion = "My sister was where??  Therylune doesn't mind getting herself dirty, but still!  That's a long way to wander, and the Master's Glaive is an unwholesome place...\n\nWell thank you, {name}.  It was very nice of you to let me know she's all right." } })
apply(947, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Pilze, {name}? Wart Ihr in der Höhle?", completion = "Vielen Dank, {name}. Das sind wirklich Prachtexemplare von Pilzen!\n\nHabt Ihr, als Ihr in Cliffspring Falls wart, etwas gefunden, das die Warnungen der Urtume bestätigen könnte?\n\nDie Urtume sind weise, aber dieses Mal hatte ich gehofft, dass sie sich irren würden." }, enUS = { progress = "Do you have my mushrooms, {name}?  Have you been to the cave?", completion = "Many thanks, {name}.  These mushrooms are fine specimens!\n\nAnd when you were at Cliffspring Falls, did you find anything to confirm the warnings of the Ancients?\n\nThe Ancients are wise, but I had hoped that, this time, they were wrong." } })
apply(948, { "classic", "forever" }, { deDE = { completion = "{name}. Da seid Ihr ja.\n\nGut.\n\nWir haben etwas... zu besprechen. Ihr und ich." }, enUS = { completion = "{name}.  You are here.\n\nGood.\n\nWe have matters...to discuss.  You and I." } })
apply(949, { "classic", "forever" }, { deDE = { completion = "Dieses Buch wurde von Hand gedruckt und ist in einer uralten Sprache geschrieben sowie von einem großen Künstler illustriert worden." }, enUS = { completion = "This book is hand printed in an ancient language, and illustrated by a master artist." } })
apply(950, { "classic", "forever" }, { deDE = { progress = "{name}. Ihr seid zurückgekehrt.", completion = "Dieses Pergament voller Gekritzel umgibt eine chaotische, primitive Magie. Ich spüre das Wirken der Altvorderen darin.\n\nHoffen wir, dass es uns Aufschluss über die Absichten des Klans der Twilight-Hammer in Dunkelküste gibt..." }, enUS = { progress = "{name}.  You return.", completion = "A chaotic, primal magic surrounds this parchment of scribbles.  I sense the work of the old ones in it.\n\nLet us hope it reveals the purpose of the Twilight's Hammer in Darkshore..." } })
apply(951, { "classic", "forever" }, { deDE = { progress = "{name}. Hat Eure Suche in den Ruinen von Mathystra etwas ergeben?", completion = "Danke. Diese Relikte stammen aus einer Zeit, als Mathystra noch glanzvoll erstrahlte. Diese einst so große Bastion der Elfen schwand dahin, doch Splitter ihrer Magie sind immer noch dort zu finden. Hoffentlich können wir die Geheimnisse dieses Ortes vor unseren Feinden enthüllen...\n\nSeid wachsam, {name}." }, enUS = { progress = "{name}.  Has your rooting through the Ruins of Mathystra been fruitful?", completion = "Thank you.  These relics are from a time when Mathystra shone.  That once great bastion of the elves has faded, but shards of its magic remain.  Let us hope we can unlock the secrets of that place before our enemies...\n\nBe vigilant, {name}." } })
apply(952, { "classic", "forever" }, { deDE = { progress = "Ah. {class}. Wie kann Onu Euch helfen?", completion = "Ah. Danke, {name}. Es ist jedoch seltsam. Der Erzdruide scheint immer so in Eile zu sein. Der Wald weiß, dass gut Ding Weile braucht. Shan’do Stormrage hat das verstanden." }, enUS = { progress = "Ah. {class}. How may Onu assist you?", completion = "Ah. Thank you, {name}. It is strange, though. The Arch Druid always seems in such a hurry. The forest knows that all shall come to pass in the appointed time. Shan'do Stormrage understood that." } })
apply(954, { "classic", "forever" }, { deDE = { completion = "Ahhh... Womit habe ich die außerordentlich große Ehre Eurer Begleitung verdient, oh {race}? Wahrlich sagt dies viel über meine momentanen Gefährten aus - ohne meine Gastgeber, die edlen Grells und Satyrn, beleidigen zu wollen -, aber man könnte Eure Anwesenheit durchaus als Verbesserung betrachten.\n\nAber bitte, lasst Euch durch mein unzivilisiertes Gerede nicht von hier vertreiben. Es ist in der Tat schon viele Jahre, sogar Jahrzehnte her, dass ich solch höfliche Begleitung hatte." }, enUS = { completion = "Ahh... To what could I possibly owe the exceedingly special honor of a {race} such as yourself as company. Truly it says much of my current companions--with no offense to my hosts, the noble grells and satyrs--that your presence could be considered an improvement.\n\nBut please, do not let my uncivil tongue drive you from the place. It has indeed been many years, decades even, since I had civil accompaniment." } })
apply(955, { "classic", "forever" }, { deDE = { progress = "Sobald ich die Ohrringe habe, werde ich den Zauber wirken, mit dem man den Standort des Siegels, das mich bindet, finden kann. Seit Jahrhunderten denke ich nur noch an die Freiheit, die die Zerstörung des Siegels mir bringen wird... Vielleicht haben all diese Jahrhunderte jedoch ihren Tribut an meinen Geist gefordert, den ich nie wieder beheben kann...", completion = "Wirklich... Die Grells von Bashal'Aran besitzen nicht, wonach ich suche... Sie sind jedoch erst kürzlich damit in Berührung gekommen. Kürzlich... Kürzlich im Sinne Eures Zeitverständnisses, nicht meines. Kürzlich reicht für mich bis in die Schatten der Vergangenheit zurück, fast bis in ein anderes Zeitalter..." }, enUS = { progress = "Once I have the earrings, I will cast the spell to search for the whereabouts of the seal that binds me. For centuries I have thought on the freedom destroying the seal would bring to me... Perhaps those centuries have taken a toll upon my mind that I might never recover...", completion = "Indeed... The grells of Bashal'Aran do not possess that which I am searching... however they have come into contact with it recently. Recently... I would reckon that by your time, not mine. Recent for me stretches into the veil of the past, almost another Age..." } })
apply(956, { "classic", "forever" }, { deDE = { progress = "Die Säulen dieses Schreins wirken auf mich wie die Gitterstäbe eines Gefängnisses, {name}. Keine der Kräfte, die ich noch besitze, könnte sie zerstören, auch keine Magie, derer ich fähig wäre...\n\nTausend Jahre oder länger habe ich sie angestarrt und mich gefragt, ob ich dann frei sein würde, wenn ich schließlich selbst die Steine überlebt hätte? Oder würden es dann unsichtbare Gitterstäbe sein, die mich hielten...", completion = "Es... es fällt mir schwer zu glauben, dass dies, was ich hier in meiner Hand halte, das ist, was mich so lange gebunden hat. Lasst uns keine Zeit verlieren, {name}. Wenn das Siegel erst zerstört ist, kann ich endlich wieder frei durch die Wälder der Erde streifen." }, enUS = { progress = "The pillars of this shrine are as the bars of a prison to me, {name}. No strength I still possess might break them, and no magic I wield might destroy them...\n\nFor a thousand years and more I have stared at them, wondering if at long last I outlived even the stone, would I be free? Or would it be invisible bars that held me then...", completion = "It... it is hard for me to even believe that what I hold now is that which has held me for so long. Let us waste no time, {name}. When the seal is destroyed, I might walk the forests of the earth freely again." } })
apply(957, { "classic", "forever" }, { deDE = { completion = "Ich bin frei, {name}! Jetzt kann ich mit eigenen Augen ansehen, wie sich unsere Welt verändert hat... Ich habe nur Teile davon gekannt. Stellt Euch vor, als ich das letzte Mal frei umherwandeln konnte, stand der Brunnen noch und die Hochgeborenen hielten Hof mit Azshara, unserer geliebten Königin.\n\nIch spüre, dass Athrikus, mein Kerkermeister, mein ehemaliger Meister, noch lebt... Das Gefühl der Hoffnungslosigkeit in mir beginnt jetzt schon, den Gedanken an Rache zu weichen." }, enUS = { completion = "I am freed, {name}! I can now see with my own eyes the changes that have come to our world... Only bits and pieces have I known. To think that when I last walked freely, the Well still stood and the Highborne held court with Azshara, our beloved queen.\n\nI sense that my jailor, my former master, Athrikus, still lives... Already my feelings of hopelessness will give way into thoughts of vengeance." } })
apply(958, { "classic", "forever" }, { deDE = { progress = "Wären die Relikte doch auch bei der Katastrophe zerstört worden, die unsere Welt zerstört hat... Wie dem auch sei, wir müssen tun, was wir können, um dafür zu sorgen, dass die Schrecken unserer Vergangenheit sich in der Zukunft nicht wiederholen.", completion = "Auch wenn ich es mir sicherlich nur einbilde, scheint es mir doch, als könnte ich bei ihnen fast die Besudelung mit übler Magie der Hochgeborenen spüren. Ich möchte sie zerstört sehen, damit dieses seit langem schlummernde Böse nie wieder freigesetzt werden kann." }, enUS = { progress = "If only the tools of their undoing could have been destroyed in the cataclysm that destroyed our world... Nonetheless, we must do what we can to ensure that the horrors of our past are not repeated in the future.", completion = "Though it is surely a figment of my imagination, I feel as though I can almost feel the taint of foul Highborne magic upon them. I will have these destroyed, so that their long dormant evil might never be released again." } })
apply(959, { "classic", "forever" }, { deDE = { progress = "Der Dockmeister sitzt mir im Nacken, seit Zausel der Verrückte mit dem 99-jährigen Portwein stiften gegangen ist. Ich glaube, diese Flasche sollte ein Geschenk an Gazlowe von keinem Geringeren als Baron Revilgaz persönlich sein.\n\nWenn Ihr mutig und geduldig genug seid, um Zausel den Verrückten aufzustöbern und ihm diesen Portwein abzunehmen, sorge ich dafür, dass Ihr eine ordentliche Belohnung bekommt.", completion = "Ausgezeichnet! Gerade, als ich dachte, ich würde meinen Job verlieren! Ich werde dafür sorgen, dass Gazlowe umgehend sein Geschenk bekommt.\n\nDanke, {name}. Das habt Ihr wirklich toll gemacht!" }, enUS = { progress = "The dockmaster has been on my case ever since Mad Magglish made off with that 99-year-old port. I guess that bottle was intended as a gift for Gazlowe from none other than Baron Revilgaz himself.\n\nIf you're brave enough and patient enough to seek out Mad Magglish and get that port back, I'll see to it you get a nice reward.", completion = "Superb! And just as I was about to lose my job too! I will see to it that Gazlowe gets this gift immediately.\n\nThank you, {name}. Nicely done, I say!" } })
apply(962, { "classic", "forever" }, { deDE = { progress = "Ich kann es kaum erwarten zu erfahren, ob Ihr in den Höhlen des Wehklagens genügend Schlangenflaum sammeln konntet. Ich habe schon viele zu diesem Zweck ausgeschickt, doch keiner kam zurück.", completion = "Ah, das sind herrliche Exemplare. Das habt Ihr gut gemacht, {name}." }, enUS = { progress = "I am eager to see if you can gather enough Serpentbloom from the Wailing Caverns. I've sent many to do my bidding but none have returned.", completion = "Ah, splendid specimens. You have done well, {name}." } })
apply(963, { "classic", "forever" }, { deDE = { progress = "Mit sorgenschwerem Herzen folgte ich Shan'do Stormrage in den Großen Schlaf und nahm meine Sorgen mit hinüber in meine Träume, um Tausende von Jahren zu schlafen.", completion = "Danke, {name}. Vielleicht wäre es besser gewesen... wenn ich es selbst getan hätte. Aber selbst nach diesen Tausenden von Jahren konnte ich es nicht über mich bringen, die Hand gegen meine Geliebte zu erheben.\n\nBitte, ich möchte mit meiner Trauer allein sein..." }, enUS = { progress = "With a great sorrow in my heart, I followed the Shan'do Stormrage into hibernation, and took my sorrow to my dreams, sleeping for the passing of thousands of years.", completion = "Thank you, {name}. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.\n\nPlease, I would be alone with my grief..." } })
apply(964, { "classic", "forever" }, { deDE = { progress = "Tötet viele und tötet häufig, {class}... wir werden einen guten Vorrat geeigneter Skelettfragmente benötigen, um die äußere Schicht des Schlüssels herzustellen. Man nennt so etwas nicht umsonst Skelettschlüssel, wisst Ihr.", completion = "Das wird funktionieren, {name}! Jetzt bin ich dran... ich werde sie mit einem geeigneten Härter tränken, wodurch sie den starken Schmiedeprozess überstehen werden, den sie schließlich durchlaufen müssen.\n\nDer nächste Schritt wird sein, eine geeignete Form für den Schlüssel zu bekommen. Ich kenne einen Goblin-Schmied in Tanaris, der in der Vergangenheit Formen für ähnlich makabre Dinge hergestellt hat. Er arbeitet für den üblichen Auftraggeber der Goblins - den höchsten Bieter." }, enUS = { progress = "Kill many and kill often, {class} - we'll need a decent supply of suitable skeletal fragments to make up the outer layer of the key.  They don't call it a Skeleton Key for nothing, you know.", completion = "This'll work, {name}!  My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.\n\nThe next step will be to get an appropriate mold for the key.  I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items.  He works for whom goblins usually work for - the highest bidder." } })
apply(965, { "classic", "forever" }, { deDE = { completion = "Elissa hat Euch geschickt? Dann bringt Ihr also gute Nachrichten. Ich habe ihr beunruhigende Neuigkeiten zu berichten und wusste nicht, wie ich sie ihr übermitteln sollte." }, enUS = { completion = "Elissa sent you? Then it is good tidings you bring. I have troubling news to report to her, and had no means with which to deliver it." } })
apply(966, { "classic", "forever" }, { deDE = { progress = "Habt Ihr noch mehr von ihren Rollen gefunden? Falls Ihr sie findet, könnte ich die Stücke zusammensetzen und mir so ein besseres Bild dieses Klans machen.", completion = "Vielen Dank, {name}. Das sollte ein wenig Licht auf diese Hexenmeisterzusammenkunft werfen...\n\nHmmm... der Kult des dunklen Strangs... Von einer solchen Gruppe habe ich noch nie gehört. Da ich nichts über ihren Hintergrund weiß, ist es fast unmöglich etwas darüber zu sagen, was sie planen könnten.\n\nEs darf keine Zeit mehr verschwendet werden. Es muss unverzüglich eine Warnung an Delgren überbracht werden." }, enUS = { progress = "Have you found any more of their scrolls? I should be able to piece together a larger picture of the cult if you can find them.", completion = "Many thanks, {name}. This should shed some light on this warlocks' gathering...\n\nHmm... the Cult of the Dark Strand... I have never heard of this group before. Having no knowledge of their history, it is all but impossible to say what their plans must be.\n\nThere is no more time to delay. Warning must be delivered to Delgren immediately." } })
apply(967, { "classic", "forever" }, { deDE = { progress = "Ihr wolltet mich sprechen, {class}?", completion = "Ihr seid ganz schön gut ausgerüstet für einen Boten, wenn ich das sagen darf, hm? Ich nehme an, Balthule wollte sichergehen, dass mich dieser Brief auch erreicht. Mal sehen, was er schreibt...\n\nDas sind beunruhigende Neuigkeiten. Wenn wirklich untote oder dämonische Streitkräfte entdeckt werden, helfe ich den Schildwachen, sie zu vernichten.\n\nIch musste mich erst an die Umgangsformen der Nachtelfen gewöhnen, aber mittlerweile habe ich vor ihnen als Verbündete größten Respekt." }, enUS = { progress = "You have some business with me, {class}?", completion = "If you don't mind my saying, you seem a bit well-equipped for a messenger, hm? I suppose Balthule wanted to be certain that his letter reached my hands. Let's see what he has to say...\n\nThis is disturbing news. When undead or demonic forces are found, I help the Sentinels destroy them.\n\nAt first I was unaccustomed to the manners of the night elves, but I have grown to respect them greatly as allies." } })
apply(968, { "classic", "forever" }, { deDE = { progress = "Hallo, werter Herr.\n\nDarf ich Euch ein paar meiner Folianten zeigen?", completion = "Ah, ein Exemplar von \"Die Macht in der Tiefe\". Ein interessantes Werk, wirklich. Manche könnten es nützlich finden...\n\nAber das hier ist in einem traurigen Zustand. Und seht nur hier! Fast alle Seiten sind mit Randnotizen versehen!\n\nHm... Ich kenne dieses Exemplar. Ich hab es letztes Jahr an Bolgar verkauft. Seid Ihr... ein Freund von ihm? Ja, das dachte ich mir schon. Ihr habt dasselbe Feuer in den Augen!\n\nTja, ich sage immer, Bolgars Freunde sind auch meine Freunde. Und wir halten zusammen, stimmt's?" }, enUS = { progress = "Hello, sir.\n\nMay I interest you in one of my tomes?", completion = "Ah, a copy of The Powers Below.  An interesting text, this is.  And some might find it useful...\n\nBut this one's in sad shape.  And look here!  There are notes in the margin of almost every page!\n\nHm...I know this copy.  I sold it to Bolgar last year.  Are you...a friend of his?  Yes, I thought you were.  You have that same fire behind your eyes!\n\nWell, by definition, a friend of Bolgar's is a friend of mine.  And we take care of our own, yes?" } })
apply(970, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Seelenedelstein?", completion = "Hmm, dieser Seelenstein ist von dunkler Magie verzaubert. Mal sehen, was sich darin verbirgt, ja?" }, enUS = { progress = "Have you acquired that soul gem?", completion = "Hmm, some dark magic enchants this soulstone. Let's see what's trapped inside, shall we?" } })
apply(971, { "classic", "forever" }, { deDE = { progress = "Die Reise nach Ashenvale ist lang und Eure Aufgabe ist nicht leicht. Aber wenn Ihr mir das Manuskript bringt, {name}... dann werde ich Euch fürstlich belohnen.", completion = "Ihr habt das Manuskript gefunden! Was für ein Freudentag! Wir werden es nachdrucken und verteilen, und dann können auch meine Brüder und Schwestern endlich des alten Wissens von Lorgalis teilhaftig werden!\n\nIhr habt uns mehr geholfen als Ihr ahnt, {name}. Ich hoffe jedoch, dass dieses Geschenk Euch zeigt, wie dankbar wir uns unseren Verbündeten erweisen." }, enUS = { progress = "The journey to Ashenvale is long, and your task is not easy.  But if you get me the manuscript, {name}...then your reward will be great.", completion = "You found the manuscript!  What a joyous day this is!  Copies will be made and distributed, and the ancient knowledge of Lorgalis will finally be known to my brothers and sisters!\n\nYour service to us is more than you know, {name}.  But I hope that this gift shows you the gratitude we extend to our allies." } })
apply(973, { "classic", "forever" }, { deDE = { progress = "Ihr scheint mir ein bisschen aufgewühlt zu sein, {name}. Seid Ihr wohlauf?", completion = "Ihr habt heute Großes geleistet, {name}. Ihr könnt sehr stolz auf Euch sein, dass Ihr Euch einem so mächtigen Hexenmeister gestellt habt.\n\nDann sehen wir doch mal, was wir aus Ilkruds Schriften lernen können." }, enUS = { progress = "You look a bit shaken up, {name}. Are you well?", completion = "It was a grand thing you did today, {name}. You should be quite proud of yourself for having faced down a warlock of such power.\n\nNow, let's see what we can learn from Ilkrud's writings." } })
apply(974, { "classic", "forever" }, { deDE = { progress = "Ich würde ja selbst gehen, aber... Ich habe ein wenig Angst vor den Feuerelementar dort!", completion = "Ja, ich sehe da ganz klar eine Verbindung zwischen der Temperatur des Vulkans und den heißen Quellen. Ich muss meine Berechnungen noch einmal auf ihre Genauigkeit überprüfen, aber es scheint, als ob die Entfernung und das Maß, mit dem die Hitze übertragen wird ... Hmm ..." }, enUS = { progress = "I'd go there myself, but... I'm a little scared of the fire elementals there!", completion = "Yes, I definitely see the correlation here between the temperature of the volcano and the hot springs. I'll have to double-check my equations for accuracy, but it seems like the distance and the rate that the heat is transferred... Hmm..." } })
apply(975, { "classic", "forever" }, { deDE = { completion = "Hier, {name}. Denkt daran, dass Ihr ihn bei Euch tragen müsst. Warum begebt Ihr Euch nicht zurück in die Wildnis und seht, was Ihr dort findet?" }, enUS = { completion = "Here it is, {name}. Remember, ya have ta carry it with you. Why don't ya head back to da wilds, an' see what ya be findin' there?" } })
apply(976, { "classic", "forever" }, { deDE = { completion = "Das habt Ihr heute gut gemacht, {class}. Die Gegenstände, die wir Auberdine zu Hilfe geschickt haben, werden umgehend gegen die dunklen Bedrohungen eingesetzt, die den Wald heimsuchen.\n\nNehmt das hier zusammen mit meinem tief empfundenen Dank." }, enUS = { completion = "You have done well today, {class}. The items we sent to aid Auberdine will be of immediate use in dealing with the dark threats that infest the forest.\n\nTake these with my heartfelt thanks." } })
apply(977, { "classic", "forever" }, { deDE = { progress = "Ich bin fast fertig mit dem Anbringen des Fells, {name}. Bitte, kommt schnell mit diesen Hörnern zurück!", completion = "Ich kann es gar nicht erwarten, das meinen Freunden zu zeigen! Also, wartet einen Moment, während ich die hier festmache...\n\nPerfekt!" }, enUS = { progress = "I've just about finished attaching the fur, {name}. Please, hurry back with those horns!", completion = "I can't wait to show my friends! Now, just wait a moment while I attach these...\n\nPerfect!" } })
apply(978, { "classic", "forever" }, { deDE = { progress = "Woher können diese Kräfte stammen? Ich glaube, wir sind auf der richtigen Spur, um die Antwort zu finden, {name}.", completion = "Jetzt kann ich diese Federn vergleichen... Mal sehen..." }, enUS = { progress = "Where could these powers have originated from? I think we are on the right track to find the answer, {name}.", completion = "Now I can compare the feathers... Let's see..." } })
apply(979, { "classic", "forever" }, { deDE = { completion = "Hallo! Erelas hat Euch geschickt? Sehr gut, ich wollte gerade zu den Höhlen reisen und ich hätte nichts gegen Begleitung." }, enUS = { completion = "Hi! Erelas sent you? Great, I was just preparing to travel up to the caves now, and I wouldn't mind company." } })
apply(980, { "classic", "forever" }, { deDE = { completion = "Hallo, {name}. Ja, es stimmt, was Krakle Euch erzählt hat..." }, enUS = { completion = "Hi there, {name}. Yes, what Krakle told you is true..." } })
apply(981, { "classic", "forever" }, { deDE = { completion = "Ich wusste, dass Ihr der Aufgabe gewachsen sein würdet, {name}.\n\nIch fühle, dass große Taten vor Euch liegen und dass Ihr viel Ungemach beseitigen werdet, das unser Land plagt. Habt meinen Segen, {name}, und dieses Geschenk." }, enUS = { completion = "I knew you would be up to the task, {name}.\n\nI sense great deeds before you, and that you will right many of the wrongs that plague our lands. Bear my blessings, {name}, as well as this gift." } })
apply(982, { "classic", "forever" }, { deDE = { progress = "Die Kapitäne dieser Schiffe waren gute Nachtelfen und sie haben ein besseres Schicksal als dieses verdient. Vielleicht ist die beste Möglichkeit, ihren Seelen Frieden zu geben, sich um ihr persönliches Eigentum zu kümmern.", completion = "Ihr habt uns hier in Auberdine einen großen Dienst erwiesen, Jungchen. Wir werden dafür sorgen, dass sich jemand ordentlich um ihr Eigentum kümmert.\n\nUnd was Euch angeht, bitte nehmt dies. Es ist das Geringste, das ich für jemanden tun kann, der den Mut hat, etwas in Ordnung zu bringen." }, enUS = { progress = "The captains of those ships were good night elves, and they deserve a better fate than they were given.  Perhaps tending to their personal effects will be the best way to put their spirits to rest.", completion = "You've done us here in Auberdine a great service, lad.  We'll make sure that their effects are properly taken care of.\n\nAs for you, please have this.  It is the least I can do for someone with the bravery to set things right." } })
apply(983, { "classic", "forever" }, { deDE = { progress = "Dröhnkiste 827 ist gespenstisch still. Eine einzelne blinkende Lampe zeigt an, dass sechs Kriecherbeine ins Gehäuse eingebaut werden müssen.", completion = "Sobald Ihr die Kriecherbeine in die Maschine eingebaut habt, hört Ihr, wie sich ein Getriebe in Gang setzt. Anhand der Klopfgeräusche, die aus der Dröhnkiste dringen, erkennt Ihr, dass Ihr die Kriecherbeine wohl an den richtigen Stellen eingebaut habt. Bald darauf beginnt die Maschine zu summen und Ihr könnt eine leise Stimme hören, die aus ihrem Inneren dringt.\n\n\"Hallo? Ähhh ... Hallo! Ihr habt sie repariert! Hier ist übrigens Wizbang! Vielen Dank ... He, Ihr habt nicht zufällig Lust, noch eine zu reparieren, was?\"" }, enUS = { progress = "Buzzbox 827 sits with an eerie silence. A single flashing light indicates that it needs 6 Crawler Legs to be placed in its holding box.", completion = "As you place the Crawler Legs inside the machine, you hear gears begin to grind. Judging from the banging sounds coming from the Buzzbox, you believe the Crawler Legs are being put in their proper place. Soon the machine begins to hum, and you hear a tiny voice calling out from within.\n\n\"Hello? Uhh... Hello! You fixed it! This is Wizbang by the way! Thanks a lot... Hey, you wouldn't want to fix another one, would ya?\"" } })
apply(984, { "classic", "forever" }, { deDE = { completion = "Das sind wahrlich schreckliche Neuigkeiten, {name}.\n\nDa die Furbolgs so nah bei Auberdine leben, müssen wir uns auf das Unausweichliche vorbereiten.\n\nDanke, {name}." }, enUS = { completion = "This is terrible news indeed, {name}.\n\nWith the furbolgs this close to Auberdine, we will have to prepare ourselves for the inevitable.\n\nThank you, {name}." } })
apply(985, { "classic", "forever" }, { deDE = { completion = "Wascht Euch das Blut von den Gewändern und trauert nicht über das, was Ihr tun musstet, {name}. Lasst Euch lieber danken. Ihr habt die Bedrohung für unser Volk hier in Auberdine verringert, obwohl Dunkelküste durch die Auswirkungen des Teufelsmooses immer noch in Gefahr ist." }, enUS = { completion = "Wash the blood from your garments, {name}, and do not mourn what you had to do. Instead, give thanks. You have lessened the threat to our people here in Auberdine, even if Darkshore is still in jeopardy from the effects of fel moss." } })
apply(986, { "classic", "forever" }, { deDE = { progress = "Ich kann Euch nicht guten Gewissens erlauben, nach Volcor zu suchen, bevor ich Euren Umhang fertig habe.", completion = "Die eignen sich bestens, {name}. Ich werde mich sofort an die Arbeit machen.\n\nGebt mir einen Moment Zeit und kommt dann wieder zu mir.\n\nOh, noch eines: sobald Ihr die Verzauberung des Umhanges benutzt, könnt Ihr nur noch eingeschränkt mit anderen interagieren. Ihr solltet, wenn möglich, nur mit ihnen sprechen. Andere Aktionen könnten die Illusion zerstören." }, enUS = { progress = "I can't in good conscience permit you to seek Volcor until I've crafted that cloak for you.", completion = "These will do nicely, {name}. I shall set to work on the cloak immediately.\n\nGive me a few moments, then return to me.\n\nOh, one more thing: after you've used the enchantment on the cloak you'll be limited in your interactions with others. If you can help it, do no more than speak to others. Much more than that could dispel the illusion." } })
apply(990, { "classic", "forever" }, { deDE = { completion = "Ah, ein {class} aus Dunkelküste. Eine gute Entscheidung Selarins, Euch so schnell hierher zu schicken, {name}. Ich wünschte, Eure Reise hierher hätte unter glücklicheren Umständen stattgefunden. Vielleicht können wir ja mit Eurer Hilfe einige Dinge verbessern.\n\nIch würde meinen Besuch mit einem Gespräch mit den anderen Bürgern von Astranaar beginnen. Einige können sicherlich Eure Hilfe gebrauchen." }, enUS = { completion = "Ah, a {class} from Darkshore. Selarin has done well to send you here so quickly, {name}. I wish your trip here wasn't under such dire stress. Perhaps with your help we can improve matters.\n\nI would start my visit by speaking to the other citizens of Astranaar. Some could surely use your aid." } })
apply(991, { "classic", "forever" }, { deDE = { completion = "Teronis' Körper liegt zerschmettert auf der Insel. Aus unbekanntem Grund haben die Murlocs von ihm abgelassen.\n\nDie tiefen Schnittwunden an seinem Kadaver stammen offensichtlich von den Waffen und Klauen der Murlocs." }, enUS = { completion = "Teronis' body lies broken atop the island. For some unknown reason, the murlocs have left it alone.\n\nThe deep slashes across his corpse obviously came from the weapons and claws of the murlocs." } })
apply(992, { "classic", "forever" }, { deDE = { progress = "Willkommen, Unterfeldmesser {name}! Habt Ihr Eure Aufgabe schon erfüllt?", completion = "Was ist das? Ihr seid in einen Hinterhalt von bösartigem, gruseligem Kriechgetier geraten? Oh, das sieht nicht gut aus für die Gadgetzan Water Company, nein, wirklich nicht...\n\nIch hätte Euch wohl von den Berichten erzählen sollen, die wir über verrückte Käferkreaturen erhalten, die anscheinend alles Wasser in der Wüste aufsaugen. Zuerst dachte ich, es wäre nur das Geschwafel eines Betrunkenen. Wir haben so schon genug Ärger mit den Nomaden; ich dachte, es wäre nur ein weiterer Schwindel von ihnen. Nun wissen wir wenigstens Bescheid!" }, enUS = { progress = "Welcome back, Junior Surveyor {name}!  Have you completed your assignment yet?", completion = "What's this?  You were ambushed by some sort of bad mojo creepy-crawly?  Oh, this does not bode well for the Gadgetzan Water Company, no indeed...\n\nI guess I should have told you about the reports coming in on some crazy bug-creatures that appear to be sucking up all the water in the desert.  At first, I thought it was just a crock.  We have enough trouble with the nomads as is; I thought it was just more of their shenanigans.  Well, now we know at least!" } })
apply(993, { "classic", "forever" }, { deDE = { completion = "Großartig! Terenthis hat jemanden gefunden, der mir helfen wird.\n\nUnd seht doch, ein Mondpirscherumhang... <hustet> Oh... das tut weh. Danke, {name}.\n\nDie Furbolgs haben mich verwundet, bevor ich ihnen entkommen konnte. Lasst mich einen Moment ausruhen, dann sollte es mir wieder besser gehen und wir können uns weiter unterhalten." }, enUS = { completion = "Wonderful! Terenthis found someone to help me.\n\nAnd look, a moonstalker cloak...<cough> Oh... that hurts. Thank you, {name}.\n\nThe furbolgs wounded me before I managed to evade them. Give me a moment, and I should be fine to talk some more." } })
apply(994, { "classic", "forever" }, { deDE = { completion = "{name}! Wie ich mich freue, dass Ihr erfolgreich zurückgekehrt seid. Eure Unterstützung für Volcor hat mich zuversichtlich gemacht, dass wir die bevorstehenden Herausforderungen hier in Dunkelküste und außerhalb meistern können." }, enUS = { completion = "{name}! I'm pleased to see you've returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond." } })
apply(995, { "classic", "forever" }, { deDE = { completion = "{name}! Wie ich mich freue, dass Ihr erfolgreich zurückgekehrt seid. Eure Unterstützung für Volcor hat mich zuversichtlich gemacht, dass wir die bevorstehenden Herausforderungen hier in Dunkelküste und außerhalb meistern können." }, enUS = { completion = "{name}! I'm pleased to see you've returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond." } })
apply(997, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas für mich?", completion = "Ah, es ist da! Ich habe schon eine ganze Weile auf diese rare Erde gewartet. Hoffentlich ist sie noch frisch...\n\nDanke, dass Ihr sie mir gebracht habt, {name}. Ihr seid ein {race}, der sich noch die Zeit nimmt." }, enUS = { progress = "You have something for me?", completion = "Ah, it's here!  I have waited for this rare earth for quite some time.  I hope it's still fresh...\n\nThank you for bringing it to me, {name}.  You are a {race} who is generous with his time." } })
apply(1000, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}.\n\nEs freut mich zu sehen, dass jemandem wie Euch das Wohlergehen der Natur am Herzen liegt. Die Geschichten über Eure großartigen Taten sind Euch vorausgeeilt und Ihr seid hier herzlich willkommen. Wenn ich Euch so sehe, erweckt Ihr in mir ein Gefühl der Zuversicht, dass der Zirkel des Cenarius genau die Hilfe bekommt, die er braucht.\n\nUnsere Verbindung zum Zirkel des Cenarius in Moonglade überwindet selbst völkische und politische Abgründe. Denkt daran, wenn Ihr im Namen des Zirkels agiert, dann wird Euch alles gut gelingen." }, enUS = { completion = "Greetings, {class}.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here.  Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides.  Remember this as you work on behalf of the Circle, and you will do well." } })
apply(1001, { "classic", "forever" }, { deDE = { progress = "Der Deckel der Maschine ist offen und scheint gespannt darauf zu warten, dass drei Drescheraugen eingebaut werden.", completion = "Die Dröhnkiste erwacht summend zum Leben, kaum dass Ihr die Drescheraugen eingebaut habt. Einen Moment lang ist nur statisches Rauschen zu hören, dann erklingt leise eine bekannte Stimme.\n\n\"Kriecherwein ist der Beste...\" *Hick*\n\n\"Was? Oh, Ihr habt sie schon repariert? Mann, Ihr seid abba schnell. Also, möchtet Ihr noch 'ne andere reparier'n?\"\n\nIhr meint zu hören, wie Flüssigkeit in einen Becher gegossen wird, gefolgt von lauten Schluckgeräuschen." }, enUS = { progress = "The machine's hatch is open and it seems to wait expectantly for 3 Thresher Eyes to be placed inside.", completion = "The Buzzbox hums to life soon after you place the Thresher Eyes inside. There is a moment of static before you hear a familiar tiny voice call out.\n\n\"Crawler wine is the best...\" *hic*\n\n\"What? Oh, you fixed it already? Wow, you're a fasht one. Sho, would ya like to fix another?\"\n\nYou believe you hear a liquid being poured into a cup, followed by loud gulping sounds." } })
apply(1002, { "classic", "forever" }, { deDE = { progress = "Obwohl Ihr die sechs Mondpirscherfangzähne noch nicht eingebaut habt, meint Ihr doch, statische Geräusche und wirres Goblingebrabbel aus der Maschine dringen zu hören. Ob wohl ein anderer die Maschine bereits repariert hat?", completion = "Die Dröhnkiste wird plötzlich aktiv und Ihr hört das unverwechselbare Geräusch knirschender Zähne aus ihrem Inneren.\n\n\"Ssso, Ihr habt's also geschafft! Dassind ja groooßartige Neuigkeiten... Also... Warum zieht Ihr nich' weiter? Oh! Vielleicht wollt Ihr noch'n Job?\"" }, enUS = { progress = "Though you have yet to place the 6 Moonstalker Fangs inside, you believe you hear the sounds of static and incoherent gnome ramblings coming from within. Could someone else have fixed the machine already?", completion = "The Buzzbox suddenly leaps into action, and you can hear the distinct sounds of teeth being ground to dust coming from within.\n\n\"Sho, ya made it! Thatsh exshellent newsh... Sho... Why doncha move along? Oh! Unless you want another job!\"" } })
apply(1003, { "classic", "forever" }, { deDE = { progress = "Ihr hört Gegröle aus der Dröhnkiste 525 dringen.\n\n\"Kriecherwein iss süß unn Drescherbier is toll, abba Mondpirscherfusel iss klasse. Ich mag nix mehr als Bier vom Distelbär unn bald schon krieg ich was davon!\"\n\nDer Deckel ist offen und wartet auf die vier ergrauten Skalps, während immer und immer wieder das Lied zum Besten gegeben wird.", completion = "Ihr habt also die Schkalps eingebaut? Das issja so toll... Wa...? Äh, ja, ich glaub, Ihr habt wohl gemerkt, dassich auch mit Euch schprechen kann, wenn die Dinger noch nich' eingebaut sind. Abba ich hab nich' gelogen, als ich sagte, dass die Maschinen kaputt waren!\n\nWisst Ihr, die Dröhnkisten sind nich' nur Kommunicketionsmittel, sondern brauen und destilliern auch noch guten Allohol. Tut mir Leid, dassich Euch'n bisschen reingelegt hab, abba die Nachtelfen finden's nich' so prickelnd, wenn ich in ihren Städten mit Schnaps handele. Ich hab in diese Kiste was ganz besonners getan, um Euch für Eure Bemüigkeiten zu danken. Prost!" }, enUS = { progress = "You hear singing coming from Buzzbox 525.\n\n\"Though crawler wine's shweet, and thresher ale fine, and moonstalker moonshine ish grand. There's nothing sho dear, as a thistle bear beer, and shoon I shall have shome on hand!\"\n\nThe hatch is open and awaits the 4 grizzled scalps as you hear the song repeated over and over.", completion = "\"Sho yash gotsh the scalps in? That'sh sho great... Wha? Well, yesh I shuppose ya have realized that I can speaksh to ya without the materials in the machine. But I was telling the truth when I shaid they were broken!\n\nSee, in addition to being communimacation toolsh, the Buzzboxes also brew and distill fine liquor. Shorry for any deceptshion, but the nightelves do not apprecimerate my liquor trade in their townsh. I put shomething special in thish box to show my gratitude for yer effortsh. Enjoy!\"" } })
apply(1004, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}.\n\nEs freut mich zu sehen, dass jemandem wie Euch das Wohlergehen der Natur am Herzen liegt. Die Geschichten über Eure großartigen Taten sind Euch vorausgeeilt und Ihr seid hier herzlich willkommen. Wenn ich Euch so sehe, erweckt Ihr in mir ein Gefühl der Zuversicht, dass der Zirkel des Cenarius genau die Hilfe bekommt, die er braucht.\n\nUnsere Verbindung zum Zirkel des Cenarius in Moonglade überwindet selbst völkische und politische Abgründe. Denkt daran, wenn Ihr im Namen des Zirkels agiert, dann wird Euch alles gut gelingen." }, enUS = { completion = "Greetings, {class}.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here.  Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides.  Remember this as you work on behalf of the Circle, and you will do well." } })
apply(1007, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Statuette gefunden, {name}?", completion = "Ihr habt sie gefunden! Danke, {name}!\n\nDie alte Stadt Zoram birgt viele Geheimnisse, und diese Statuette könnte der Schlüssel zu vielen davon sein." }, enUS = { progress = "Have you found the statuette, {name}?", completion = "You found it!  Thank you, {name}!\n\nThe old city of Zoram holds many secrets, and this statuette may be the key to many of them." } })
apply(1008, { "classic", "forever" }, { deDE = { progress = "Wir dürfen nicht zulassen, dass die Naga unsere Küsten besetzen, {name}. Es ist wichtig, dass Ihr zum Zoramstrand reist und Eure Mission beendet.", completion = "Sehr gut, {name}. Sehr löblich, was Ihr da am Zoramstrand gegen die Naga ausgerichtet habt.\n\nIch kann mir denken, dass Ihr es nicht leicht hattet, denn die Kraft und Arglist der Naga sind den Nachtelfen wohl bekannt. Wir wissen es, weil wir eine gemeinsame Vergangenheit haben.\n\nEine Vergangenheit, die sich auf keinen Fall wiederholen darf." }, enUS = { progress = "We cannot allow the naga to invade our coasts, {name}.  It is vital that you go to the Zoram Strand and complete your mission.", completion = "Very well done, {name}.  Your actions in the Zoram Strand against the naga are commendable.\n\nI know your feat was not easily accomplished, for the strength and guile of the naga is well known to the night elves.  We know this, for we share a history with them.\n\nIt is a history I care not to repeat." } })
apply(1009, { "classic", "forever" }, { deDE = { progress = "Es heißt, dass der Ring von Zoram der Schlüssel zu allen Schlössern der Stadt sei. Habt Ihr ihn, {name}?", completion = "Ihr habt den Ring gefunden! Danke, {name}. Bitte nehmt das hier als Lohn und wisset, dass ich Eure heutige Tat nie vergessen werde." }, enUS = { progress = "It is said that the Ring of Zoram is the key to any lock within the city.  Do you have it, {name}?", completion = "You found the ring!  Thank you, {name}.  Please take this as payment, and know that your deeds today will remain forever in my memory." } })
apply(1010, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Bathranshaar gefunden, {name}? Das Kind wird von Stunde zu Stunde schwächer...", completion = "Ah, Ihr habt das Haar! Jetzt kann ich ein Heilmittel für das Kind zusammenmischen und beten, dass mein Gebräu auch wirkt.\n\nUnd... die Verlassenen sind in Bathrans Schlupfwinkel? Das ist höchst beunruhigend. In der Tat höchst beunruhigend..." }, enUS = { progress = "Have you gathered the Bathran's Hair, {name}?  The child's health grows weaker by the hour...", completion = "Ah, you have the hair!  Now I will mix a cure for the child, and pray my concoction works.\n\nAnd... Forsaken are at Bathran's Haunt?  Very troubling to hear, that is.  Very troubling indeed..." } })
apply(1011, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Lager gefunden, {name}? Habt Ihr eine Krankheitsflasche?", completion = "Sehr gut, {name}. So... ich teste jetzt den Inhalt dieser Flasche, dann werden wir bald wissen, welche Ziele die Verlassenen verfolgen!" }, enUS = { progress = "Did you find the camp, {name}?  Do you have a bottle of disease?", completion = "Very good, {name}.  Now... by testing the contents of this bottle, the goals of the Forsaken will be revealed!" } })
apply(1012, { "classic", "forever" }, { deDE = { progress = "Der Zorn der Druiden von Dor'danil verfolgt mich immer noch in meinen Träumen, {name}. Ihr müsst ihre Anführer vernichten!", completion = "Ich fühlte, dass der Zorn der Dor'danil-Grabhügel nachließ und wusste, dass Ihr Euren Auftrag erfüllt hattet.\n\nWas Ihr tun musstet, war grausam, {name}, denn die Geister, die Ihr vernichten solltet, waren doch nur unschuldige Opfer der Bösartigkeit der Verlassenen. Hoffen wir, dass auch die anderen wahnsinnigen Geister endlich Ruhe finden, da sie jetzt vernichtet sind." }, enUS = { progress = "The anguish of the Dor'danil druids still haunt my dreams, {name}.  You must destroy their leaders!", completion = "I felt the anguish of the Dor'danil Barrows lessen, and knew you had completed your task.\n\nIt was grim work you did, {name}, for the spirits you destroyed were merely victims of the Forsaken's evil.  But with their destruction, let us hope the other maddened spirits find peace." } })
apply(1013, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Buch gefunden, {name}?", completion = "Sehr gut. Dieses Buch ist eine wunderbare Ergänzung meiner Sammlung der Werke Urs. Er wusste so viel, doch sein Gewissen hielt ihn von der wahren Macht zurück. Und als die Geißel kam und seine Kraft auf die Probe stellte, versagte er.\n\nWir Verlassene können uns eine solche Schwäche nicht leisten, wenn wir überleben wollen ...\n\n... wenn wir erobern wollen." }, enUS = { progress = "Did you find the book, {name}?", completion = "Very good.  This book will add nicely to my collections of the workings of Ur.  His knowledge was great, but his conscience held him from true power.  And so when the Scourge came and his strength was tested, it failed.\n\nWe of the Forsaken cannot afford such weakness, if we are to survive...\n\n...If we are to conquer." } })
apply(1014, { "classic", "forever" }, { deDE = { progress = "Da Arugal jetzt tot ist, können wir die Festung der dunklen Fürstin in Lordaeron stärken.", completion = "Der Silberwald ist jetzt endlich aus den Klauen dieses elenden Arugal befreit. Ihr habt der dunklen Fürstin einen großen Dienst erwiesen, {name}. Eure Beharrlichkeit soll belohnt werden." }, enUS = { progress = "With Arugal's death we stand to increase the Dark Lady's stronghold on Lordaeron.", completion = "Silverpine Forest is finally free from the vice of that wretch Arugal. You have done the Dark Lady a great service, {name}. Your tenacity shall be rewarded." } })
apply(1015, { "classic", "forever" }, { deDE = { completion = "Was macht Euch glauben, dass ich mich von Euresgleichen belästigen lasse, {class}? Wartet - lasst mich meine wichtigen Tagesgeschäfte unterbrechen, damit ich Euch helfen kann, irgendwo ein Dingelchen zu finden. Wahrhaftig, das Wohlergehen von Darnassus - ach was, von ganz Teldrassil ist nicht so wichtig wie die Beschaffung von Flitterzeug für Eure Sammlung.\n\nDiese Narren in Moonglade vergeuden meine Zeit mit ihrem Hilferuf, und jetzt muss ich mir das hier antun!" }, enUS = { completion = "What makes you think I wish to be pestered by the likes of you, {class}?  Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere.  By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?" } })
apply(1016, { "classic", "forever" }, { deDE = { progress = "Da Ihr die Armschienen zerstören müsst, um die Elementare zu töten, wird es möglicherweise schwierig sein, genau jene zu finden, die die Informationen enthalten, die von der Rolle der Bestimmung benötigt werden. Ihr könnt Armschienen auch mit anderen tauschen, um die zu erhalten, die Ihr benötigt, aber vielleicht habt Ihr das bestimmte Dokument ja auch bereits?", completion = "Gut gemacht, {name}, das sollte uns die Informationen liefern, die wir brauchen, um den Schuldigen zu entlarven. Hättet Ihr nicht Lust, den Magier auszuschalten, der unsere Teiche mit verderbten Elementaren überschwemmt? Die Verderbnis von Ashenvale und darüber hinaus dreht mir ja bereits den Magen um. Dass ein Hexer versucht, es noch weiter zu zerstören, macht mich ganz krank. Wir sollten ihn dafür bezahlen lassen." }, enUS = { progress = "Since you must destroy the bracers to kill the elementals, it will probably be difficult to find the specific ones that contain the information the divining scroll needs. You can trade bracers with others in order to obtain the ones you need, or perhaps you have the divined paper already?", completion = "Well done, {name}, this should give us the information we need to have the culprit discovered. How would you feel about taking out the mage who fills our pools with corrupt elementals? The corruption of Ashenvale and beyond makes my stomach turn on its own--to have a wizard actively attempting to destroy it further sickens me to no end. We shall make him pay." } })
apply(1017, { "classic", "forever" }, { deDE = { progress = "Ist es vollbracht? Ist Sarilus Foulborne tot?", completion = "Das hat ihm sein widerliches Grinsen ein für alle Mal aus dem Gesicht gewischt. Das habt Ihr sehr gut gemacht, {name}. Nehmt das hier, das Licht von Elune, und trinkt davon, wenn alles verloren scheint und Ihr dem Tod nahe seid. Es könnte Euch retten, so die Göttin es will." }, enUS = { progress = "Is it done? Is Sarilus Foulborne dead?", completion = "Now I can see that repugnant smile wiped from his face forever. You have done very well, {name}. Take this, the Light of Elune, drink of it when all seems lost and death is near. It may save you, Goddess willing." } })
apply(1018, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}.\n\nEs freut mich zu sehen, dass jemandem wie Euch das Wohlergehen der Natur am Herzen liegt. Die Geschichten über Eure großartigen Taten sind Euch vorausgeeilt und Ihr seid hier herzlich willkommen. Wenn ich Euch so sehe, erweckt Ihr in mir ein Gefühl der Zuversicht, dass der Zirkel des Cenarius genau die Hilfe bekommt, die er braucht.\n\nUnsere Verbindung zum Zirkel des Cenarius in Moonglade überwindet selbst völkische und politische Abgründe. Denkt daran, wenn Ihr im Namen des Zirkels agiert, dann wird Euch alles gut gelingen." }, enUS = { completion = "Greetings, {class}.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here.  Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides.  Remember this as you work on behalf of the Circle, and you will do well." } })
apply(1019, { "classic", "forever" }, { deDE = { completion = "Was macht Euch glauben, dass ich mich von Euresgleichen belästigen lasse, {class}? Wartet - lasst mich meine wichtigen Tagesgeschäfte unterbrechen, damit ich Euch helfen kann, irgendwo ein Dingelchen zu finden. Wahrhaftig, das Wohlergehen von Darnassus - ach was, von ganz Teldrassil ist nicht so wichtig wie die Beschaffung von Flitterzeug für Eure Sammlung.\n\nDiese Narren in Moonglade vergeuden meine Zeit mit ihrem Hilferuf, und jetzt muss ich mir das hier antun!" }, enUS = { completion = "What makes you think I wish to be pestered by the likes of you, {class}?  Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere.  By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?" } })
apply(1020, { "classic", "forever" }, { deDE = { progress = "Ich muss mich entschuldigen, aber ich habe jetzt keine Zeit, um zu plaudern. Meine Tochter Relara ist todkrank!", completion = "Das ist von Orendil?\n\nSeine Fertigkeiten in Kräuter- und Heilkunde sind enorm. Dieses Heilmittel gibt mir Hoffnung, dabei hatte ich schon fast aufgegeben..." }, enUS = { progress = "I must apologize, for I have no time to speak.  My child, Relara, is deathly ill!", completion = "This is from Orendil?\n\nHis skill with herbs and healing is great.  This cure gives me hope, when before I had little..." } })
apply(1021, { "classic", "forever" }, { deDE = { completion = "Den klaffenden Wunden in ihrer Seite nach zu urteilen, steht Anilia an der Schwelle des Todes." }, enUS = { completion = "Judging by the gaping wound in her side, Anilia is on the verge of death." } })
apply(1022, { "classic", "forever" }, { deDE = { completion = "Der Foliant von Mel'Thandris funktioniert auf merkwürdige Weise. Die Ereignisse, die er enthält, die Ereignisse, die er zeigt... Niemand versteht wirklich, wie er funktioniert.\n\nDennoch ist es klar, dass man näher untersuchen sollte, was die Priesterin Starsong bekommen hat - die Sense von Elune." }, enUS = { completion = "The Tome of Mel'Thandris works in strange ways. The events it records, the events it shows... No one truly understands why it does what it does.\n\nNonetheless, it is clear that what Priestess Starsong received--this Scythe of Elune--bears further investigation." } })
apply(1023, { "classic", "forever" }, { deDE = { progress = "Ah, willkommen zurück, {name}.", completion = "Wie schrecklich, {name}. Teronis ist tot?!\n\nIch werde ihn später betrauern, aber jetzt müssen wir uns zuerst auf unsere Aufgaben konzentrieren. Ich schicke ein paar der Schildwachen aus, um Teronis' Leiche so schnell wie möglich herzubringen.\n\nIhr habt Teronis' Tagebuch und den Edelstein, den er suchte. Denkt Ihr, Ihr seid imstande, diesen Auftrag auszuführen? Es würde mich beruhigen, wenn ich wüsste, dass sein Tod nicht umsonst war." }, enUS = { progress = "Ah, welcome back, {name}.", completion = "This is terrible, {name}. Teronis is dead?!\n\nThe time for mourning will come, but for now we must focus our efforts. I shall send some of the Sentinels to recover Teronis' body as soon as possible.\n\nYou have Teronis' journal and the gem he was seeking. Do you think you're capable of completing his task? I would rest much better knowing his death was not in vain." } })
apply(1024, { "classic", "forever" }, { deDE = { progress = "Hallo. Wie geht es Euch?", completion = "Oh, Raene hat Euch geschickt? Dann muss es wohl wirklich dringlich sein. Wie kann ich Euch helfen?" }, enUS = { progress = "Hello. How are you?", completion = "Oh, Raene sent you? It must be serious indeed. What can I help you with?" } })
apply(1025, { "classic", "forever" }, { deDE = { completion = "Das habt Ihr gut gemacht, {name}. Danke." }, enUS = { completion = "You have done well, {name}. Thank you." } })
apply(1026, { "classic", "forever" }, { deDE = { progress = "Es bestürzt mich sehr, dass die Treants verderbt wurden. Ich wünschte, ich könnte mehr tun, um ihnen zu helfen.", completion = "Wie ich mich freue, dass Ihr zurück seid, {name}." }, enUS = { progress = "It upsets me so that the treants have become corrupt. I wish I could do more to help them.", completion = "I'm pleased to see you're back, {name}." } })
apply(1027, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das letzte Teil der Rute gefunden, {name}?", completion = "Ihr habt das letzte Teil gefunden? Wie wunderbar für Euch... und für Raene.\n\nDann sollten wir beginnen, sie zu reparieren, meint Ihr nicht?" }, enUS = { progress = "Did you find the final piece of the rod, {name}?", completion = "You found the final piece? Wonderful for you... and for Raene.\n\nI guess we'll have to see about repairing it, won't we?" } })
apply(1028, { "classic", "forever" }, { deDE = { progress = "Ihr spürt eine subtile, doch mächtige Kraft innerhalb des Schreins und zwischen den Bäumen der Umgebung.\n\nKaum legt Ihr die Rute in den Schrein, erwacht ein sanftes Dröhnen um Euch herum und der Schrein beginnt zu glühen...", completion = "Als das Glühen erlischt, seht Ihr die erneut verzauberte Rute im Becken des Schreins liegen." }, enUS = { progress = "You can sense a subtle yet powerful force within the shrine and surrounding trees.\n\nYou begin placing the rod within the shrine and a soft thrumming noise emits from around you as the shrine begins to glow...", completion = "After the glow dies, you can see the re-enchanted rod within the shrine's basin." } })
apply(1031, { "classic", "forever" }, { deDE = { progress = "Habt Ihr sie gefunden? Was hat Anilia gesagt? Wo ist sie?", completion = "Anilia ist tot? Nein... das kann nicht sein! Noch gestern sind wir zusammen durch die Wälder getollt und haben gespielt.\n\nDiese Zeiten sind wohl jetzt vorbei..." }, enUS = { progress = "Have you found them? What did Anilia say? Where is she?", completion = "Anilia died? No... that can't be! It was just yesterday that we were running and playing together in the woods.\n\nI guess those days are over..." } })
apply(1032, { "classic", "forever" }, { deDE = { progress = "Bitte, helft mir Anilias Tod zu rächen.", completion = "Danke, {race}, Ihr seid sehr freundlich. Der Geist meiner Schwester ist dankbar für Eure Bemühungen." }, enUS = { progress = "Please, help me avenge Anilia's death.", completion = "Thank you, kind {race}. My sister's spirit is gladdened by your efforts." } })
apply(1033, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Irissee gefunden, {name}? Habt Ihr die Träne?", completion = "Oh, Ihr habt sie gefunden! Ich werde die Träne in einen Eintopf geben und beten, dass meine Tochter davon geheilt wird.\n\nDanke! Danke, {name}!" }, enUS = { progress = "{name}, did you find Iris Lake?  Do you have the Tear?", completion = "Oh, you found it!  I will place the tear in a stew, and pray that it will cure her.\n\nThank you!  Thank you, {name}!" } })
apply(1034, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Sternenstaub schon, {name}?", completion = "Ihr habt den Staub! Ich werde daraus eine Breipackung machen - vielleicht kann man damit Relaras Fieber senken.\n\nNochmals danke, {name}. Ohne Eure Hilfe würde mein Kind sicherlich sterben." }, enUS = { progress = "Do you yet have the Stardust, {name}?", completion = "You gathered the dust!  I will create a poultice from these -- it should bring down Relara's fever.\n\nThank you again, {name}.  Without your help, my child would surely perish." } })
apply(1035, { "classic", "forever" }, { deDE = { progress = "Wart Ihr schon beim Schattendickichtorakel, {name}? Falls ja, dann gebt mir doch bitte den gefallenen Mondstein. Relaras Kraft reicht nur noch für ein paar Atemzüge!", completion = "Oh, {name}, Ihr habt meine Tochter gerettet! Ich wusste, dass die Macht des Mondsteins meine Tochter wieder zu Kräften bringen könnte!\n\nKein Schatz der Erde würde ausreichen, um Euch für Eure Hilfe zu entlohnen, aber... bitte nehmt das. Außer Relara ist dies das Liebste, das ich habe." }, enUS = { progress = "Did you face the Shadethicket Oracle, {name}?  If so, then please hand me the fallen moonstone.  Relara has strength left for only a few more breaths!", completion = "Oh, {name}, you have saved my daughter!  I know the power of the moonstone will give back my daughter her strength!\n\nI can never repay you fully for the aid you have given me, but... please, take this.  Other than Relara, it is my most dear possession." } })
apply(1037, { "classic", "forever" }, { deDE = { completion = "Velinde Starsong? Dass die Priesterin vor einiger Zeit verschwand, dürfte landläufig bekannt sein. Was weitere Details der Umstände ihres Verschwindens betrifft... Ihr müsstet mir schon einen guten Grund nennen, warum ich solche Informationen preisgeben sollte." }, enUS = { completion = "Velinde Starsong? That the priestess disappeared some time ago is almost certainly common knowledge. As to further details about the events that surrounded her departure... it would take good reason for me to divulge such information." } })
apply(1038, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr herausgefunden?", completion = "Velindes Verschwinden scheint doch seltsamer zu sein, als wir dachten. Ich kann immer noch nicht glauben, dass es mit ihr ein böses Ende genommen hat. Vielleicht wäre es nützlich für uns, Kontakt zu ihr aufzunehmen.\n\n{name}, da Ihr ein berechtigtes Interesse an dieser Sache gezeigt habt, würde ich Euch gern mit einbeziehen." }, enUS = { progress = "What'd you find out?", completion = "It seems that Velinde's disappearance is more troubling than it originally appeared. Even still, I cannot believe that she has come to a bad end. Perhaps it would be beneficial for us to make contact with her.\n\n{name}, since you have shown a vested interest in this matter, I would like to enlist your aid." } })
apply(1039, { "classic", "forever" }, { deDE = { completion = "{race}, hä? Muss gestehen, solche wie Euch sieht man hier nicht oft. Sucht Ihr jemanden, hä? Einen Moment, das steht bestimmt in einer meiner Listen.\n\nHier zieht ein Haufen Volk durch, also gebt mir einen Moment Zeit." }, enUS = { completion = "{race}, eh? Must admit, we don't get much of your type out here. Looking for someone, eh? Just give me a moment, I'm sure I have it written in one of my ledgers.\n\nLot of people travel through here, though, so just give me a moment." } })
apply(1040, { "classic", "forever" }, { deDE = { completion = "Ja? Tja, Ihr seht mir nicht so aus, als hättet Ihr Waren zu befördern, also müsst Ihr wohl entweder auf der Suche nach einem Job in meiner Karawane sein - und ich habe momentan keine Jobs zu vergeben - oder Ihr sprecht mit dem falschen Goblin.\n\nAlso was liegt an?" }, enUS = { completion = "Yes? Now, it doesn't look to me like you're the sort with goods that need shipping, so either you're looking for a job with my caravan--and there's no jobs to be had now--or you're probably talking to the wrong goblin.\n\nSo which one is it?" } })
apply(1041, { "classic", "forever" }, { deDE = { completion = "Ich versuche, trotz all der seltsamen Ereignisse der letzten Jahre, so gut ich kann über alle Fremden Buch zu führen. Man weiß ja nie, wann man das mal brauchen könnte... nur ist es meistens wenig erfreulich, wenn es so ist. Nicht, dass ich damit irgendwas über diese Velinde sagen will, die Ihr sucht." }, enUS = { completion = "With all the strange happenings of the last few years, I keep as good records of strangers as I can. Never know when it might come in handy... though it's usually not pleasant business when it does. Not to suggest anything about this Velinde you're looking for." } })
apply(1042, { "classic", "forever" }, { deDE = { completion = "Das sind wahrlich düstere Zeiten. Jeder Baum und Strauch flüstert schlimme Neuigkeiten und unter jedem Stein findet man etwas Böses.\n\nUnd in solchen Zeiten spaziert ein unbekannter Fremdling in mein Haus und fragt mich nach Worgs... Ich bitte nicht um Verzeihung für meinen Argwohn, sondern um Antworten.\n\nUnd Antworten werde ich bekommen." }, enUS = { completion = "Dark times these are. Ill news is whispered from every swaying branch, and evil can be found under every rock.\n\nAnd in such times an unknown stranger enters my home and asks of worgen... I'll ask no forgiveness for my suspicions, only answers.\n\nAnd answers, I will have." } })
apply(1043, { "classic", "forever" }, { deDE = { completion = "Ihr erzählt mir da eine interessante Geschichte, {name}. Der Einfluss der Familie Carevin reicht zwar nicht so weit, dass wir die Wurzel aller Probleme finden und ein für alle Mal ausrotten könnten, aber wir tun was wir können, um die Zahl der Worgs im Dämmerwald in Grenzen zu halten.\n\nIch habe Calor bereits angewiesen, das zu seinem Hauptanliegen zu machen." }, enUS = { completion = "It is an interesting story you tell, {name}. Though the Carevin family's influence is not large enough that we might find the root of these troubles and finish them once and for all, we will do what we can to contain the worgens' numbers in Duskwood.\n\nAlready I have instructed Calor to make this his first priority." } })
apply(1044, { "classic", "forever" }, { deDE = { completion = "Das ist also Velindes Schicksal, was? Die Hohepriesterin wird enttäuscht sein, wenn sie davon erfährt. Sie und Velinde waren vor deren Verschwinden gute Freundinnen. Unsere Göttin hat ihr die Sense von Elune bestimmt als eine Art Wohltat zukommen lassen, und ich bin erschüttert, dass sie nicht mehr in den Händen ihrer Dienerin ist.\n\nAber das ist eine Angelegenheit, um die man sich später kümmern muss. Ich schulde Euch Dank für das, was Ihr geleistet habt." }, enUS = { completion = "So this is the fate of Velinde, is it? The high priestess will be disappointed to hear of this, they were good friends before her disappearance. Still, the Scythe of Elune was surely granted to her as a boon by our goddess, and it is unsettling to me that it has fallen out of her servants' hands.\n\nAnother matter for another time, however. I owe you my thanks in no small amount for what you have accomplished." } })
apply(1045, { "classic", "forever" }, { deDE = { completion = "Das habt Ihr gut gemacht.\n\nDer Wald ist zwar immer noch besudelt, aber zumindest wissen wir jetzt, dass wir einen kleinen Beitrag dazu geleistet haben, ihm seine frühere Herrlichkeit zurückzugeben. Solltet Ihr mich wieder besuchen wollen, ich würde mich sehr über die Gesellschaft mit jemandem meiner Art freuen.\n\nGehabt Euch wohl. Vielleicht treffen sich unsere Stämme einst in weniger gewalttätigen Zeiten wieder." }, enUS = { completion = "You have done well, my friend.\n\nThe forest is still tainted, but at least we know we have done a small part to return it to its former glory. If you wish to return to me again, I would enjoy the company of my own kind.\n\nBe well. Perhaps our tribes will meet again under less violent times." } })
apply(1046, { "classic", "forever" }, { deDE = { progress = "Die Schildwachen hier in Ashenvale tun was sie können, aber solchen wie Euch, {race}, verdanken wir den Boden, den wir wieder zurückgewonnen haben.", completion = "Das ist also der Schädel des wildesten Furbolg von Ashenvale?\n\nIch bin von Euren Fähigkeiten mehr als angetan, {name}. Die Schildwachen können Euch nicht genug danken. Ich hoffe, wir können uns auch in Zukunft darauf berufen, dass Ihr unserem Volk helft.\n\nDiesen Schädel und Dartols Rute werde ich an einem Ehrenplatz aufbewahren, damit jeder sie bewundern kann.\n\nTeronis wäre stolz. Nochmals danke." }, enUS = { progress = "The Sentinels do what they can here in Ashenvale, but it's thanks to {race} like you that we have gained the ground we have.", completion = "So, this is the skull of the fiercest furbolg threat in Ashenvale?\n\nI am more than pleased with your abilities, {name}. The Sentinels cannot thank you enough. I hope we can rely on you again in the future to help our people.\n\nI shall put this skull and Dartol's Rod in a place of reverence for others to see.\n\nTeronis would be proud. Thank you again." } })
apply(1047, { "classic", "forever" }, { deDE = { completion = "Was macht Euch glauben, dass ich mich von Euresgleichen belästigen lasse, {class}? Wartet - lasst mich meine wichtigen Tagesgeschäfte unterbrechen, damit ich Euch helfen kann, irgendwo ein Dingelchen zu finden. Wahrhaftig, das Wohlergehen von Darnassus - ach was, von ganz Teldrassil ist nicht so wichtig wie die Beschaffung von Flitterzeug für Eure Sammlung.\n\nDiese Narren in Moonglade vergeuden meine Zeit mit ihrem Hilferuf, und jetzt muss ich mir das hier antun!" }, enUS = { completion = "What makes you think I wish to be pestered by the likes of you, {class}?  Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere.  By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?" } })
apply(1048, { "classic", "forever" }, { deDE = { completion = "Ihr habt der dunklen Fürstin gut gedient, {class}. Es war keine leichte Aufgabe, die ich Euch da abverlangt habe.\n\nEure Loyalität gegenüber den Verlassenen ist nicht unbemerkt geblieben. Und an Eure Beharrlichkeit im Kampf wird man sich immer erinnern." }, enUS = { completion = "You have served the Dark Lady well, {class}. 'Twas no small task I asked of you.\n\nYour loyalty to the Forsaken has been noted. And your tenacity in combat will be remembered." } })
apply(1049, { "classic", "forever" }, { deDE = { progress = "Cairne ist ein mutiger und edler Anführer, und ich würde ihm mein eigenes Leben anvertrauen. Es gibt jedoch andere, denen ich in diesem politischen Klima nicht trauen kann.\n\nSobald ich die Möglichkeit habe, alles Wissen zusammenzutragen, dessen ich habhaft werden kann, würde ich dem Häuptling ein solider Ratgeber sein.\n\nWäre es Euch vielleicht möglich, nach Tirisfal zu reisen? Zum Scharlachroten Kloster? Das 'Kompendium der Gefallenen' ist nur ein Teil dieses komplizierten Puzzles...", completion = "Das 'Kompendium der Gefallenen'! Ich begann mich schon zu fragen, ob das Buch überhaupt existiert!\n\nIhr habt den Tauren von Thunder Bluff sehr geholfen, {name}. Euer Engagement soll belohnt werden." }, enUS = { progress = "Cairne is a brave and noble leader and I would trust him with my own life. But it is others that I do not trust in this political climate.\n\nOnce I have a chance to gather all the knowledge available I can provide sound council to the Chieftain.\n\nHave you had a chance to travel to Tirisfal Glades? To the Scarlet Monastery? The Compendium of the Fallen is just one piece in this complicated puzzle...", completion = "The Compendium of the Fallen! I was beginning to wonder if the very book existed!\n\nYou have served the tauren of Thunder Bluff well, {name}. Your dedication shall not be forgotten." } })
apply(1050, { "classic", "forever" }, { deDE = { progress = "Das Kloster war einst ein Seminar für in Ausbildung befindliche Paladine. Die ehemalige Festung des Lichts fiel in die Hände der irren Zeloten des Scharlachroten Kreuzzuges.\n\nDer Kreuzzug hielt das Ziel, das sie verfolgten, für edel: das Land von der Untotenseuche zu läutern. Irrsinn jedoch verzerrte ihren Schwur und jetzt sind sie jedermanns Feind.\n\nBringt mir die 'Mythologie der Titanen', damit ich sie studieren und hier in Ironforge aufbewahren kann.\n\nDie verderbten Hallen des Klosters sind kein Ort für einen solchen historischen Schatz.", completion = "Ihr habt die heiligen Schriften gerettet!\n\nEure Reise war lang, und das Buch zu bekommen, war zweifelsohne keine leichte Aufgabe. Aber die Zwerge von Ironforge werden von Eurem Erfolg sehr profitieren.\n\nIch danke Euch im Namen der Forscherliga, {name}." }, enUS = { progress = "The Monastery was a seminary for Paladins-in-training. Once a stronghold of the Light, it fell into the hands of the crazed zealots of the Scarlet Crusade.\n\nThe Crusade believed their goal a noble one: to purify the land of the undead plague. But insanity tainted their plight and now they stand enemies to all.\n\nBring Mythology of the Titans to me so I can study it and house it here in Ironforge.\n\nThe corrupt halls of the Monastery are no place for such a historical treasure.", completion = "You have rescued the sacred text!\n\nYour journey was long and acquiring the book was undoubtedly no easy task. But  the dwarves of Ironforge stand to benefit from your success.\n\nThank you, {name}, on behalf of the Explorers' League." } })
apply(1051, { "classic", "forever" }, { deDE = { progress = "Was wollt Ihr, Fremdling?", completion = "Vorrel führte ja so ein bewegtes Leben. Was war er doch für ein guter Gefährte...\n\nVerdammt seien diese dreckigen Menschen!\n\nVorrel ist fort und wird sich nie wieder am untot sein erfreuen. Zumindest finde ich Trost in der Rache, die Ihr in seinem Namen geübt habt. Dafür danke ich Euch.\n\nUnd jetzt überlasst mich meiner Trauer..." }, enUS = { progress = "What do you want, stranger?", completion = "Vorrel led such a troubled existence. And what a good mate he was...\n\nDamn those filthy humans!\n\nVorrel is gone, never to enjoy undeath again. At least I can take solace in the revenge you took in his name. For that I thank you.\n\nNow let me be to mourn...." } })
apply(1052, { "classic", "forever" }, { deDE = { progress = "Wer ist da? Was wollt Ihr von mir?", completion = "Bruder Anton verbreitet immer noch die Lehren des scharlachroten Kreuzzuges? So, so..." }, enUS = { progress = "Who goes there? What do you want from me?", completion = "Brother Anton still spreads the word of the Scarlet Crusade? Oh my...." } })
apply(1053, { "classic", "forever" }, { deDE = { completion = "Die Jünger des Lichts sind nicht erpicht darauf, ihr Leben zu lassen, doch müssen wir akzeptieren, dass manche Umstände es erforderlich machen, solche Opfer für das Wohl des Königreiches und des gesamten Planeten zu bringen.\n\nDurch Eure Taten im Kloster habt Ihr vielen Unschuldigen das Leben gerettet, {name}. Ich verbeuge mich vor Eurer Beharrlichkeit." }, enUS = { completion = "While disciples of the Light never revel in the loss of life, we must accept that on occasion, such sacrifices must happen for the greater good of the Kingdom and the planet.\n\nThrough your deeds in the Monastery you have spared many innocent lives, {name}. I salute your tenacity." } })
apply(1054, { "classic", "forever" }, { deDE = { progress = "Die Verderbnis der Furbolgs hat aus Ashenvale ein Zerrbild seines einstigen Glanzes gemacht.", completion = "Gut gemacht, {name}.\n\nDie Furbolgs sind eine ständige Bedrohung. Hoffentlich wird sie das noch eine Weile in Schach halten." }, enUS = { progress = "The furbolgs' corruption has caused Ashenvale to become a fraction of its former glory.", completion = "Well done, {name}.\n\nWe are under constant threat from the furbolg. Hopefully this will keep them at bay for a bit longer." } })
apply(1055, { "classic", "forever" }, { deDE = { completion = "Ihr habt es geschafft, {name}! Gut gemacht!" }, enUS = { completion = "You've done it, {name}! Well done!" } })
apply(1056, { "classic", "forever" }, { deDE = { completion = "Endlich seid Ihr da. Ich sehe, Faldreas hat auf die Waldgeister gehört..." }, enUS = { completion = "Finally, you arrive. I see Faldreas has listened to the forest spirits...." } })
apply(1057, { "classic", "forever" }, { deDE = { completion = "Jetzt, da die Blutfurien einen solch großen Verlust erlitten haben, können wir vielleicht endlich ernsthaft an den Wiederaufbau des Landes gehen..." }, enUS = { completion = "Now that the Bloodfuries have suffered such a great loss, perhaps the true work of restoring the land can begin...." } })
apply(1058, { "classic", "forever" }, { deDE = { progress = "Seht Euch nur unsere armen kleinen Elfenfreunde an. Eingesperrt in einen Käfig und weit und breit kein Wald, in dem sie herumtollen können!\n\nNun, habt Ihr etwas Saft für mich gefunden? Was ist mit den Schnurrhaaren der Mondlichtläufer? Ihr habt nicht zufällig diese Siechdrachen-Schuppe dabei?\n\nUnd die Augen! Ich brauche jede Menge Augen! Ohne eine ordentliche Portion Augen kann man einfach keine starke Waldmagie zusammenbrauen!", completion = "Oh, wie glücklich werden diese kleinen Waldnymphen sein! Mit diesem Spezialgebräu werden sie sich ganz wie zu Hause fühlen!" }, enUS = { progress = "Look at our poor little elf friends. All caged up with no forest to frolic in!\n\nNow were you able to find me some sap? How about the whiskers from the twilight runners? Don't suppose you have that fey dragon scale on you?\n\nAnd eyes! I'll need so many eyes! You just can't mix up a fierce forest magic brew without a good helping of eyes!", completion = "Oh how happy these little woodland nymphs shall be! We'll make them feel right at home with this special concoction!" } })
apply(1059, { "classic", "forever" }, { deDE = { completion = "Es war sehr klug von Bewahrer Albagorm, Euch so schnell zu entsenden.\n\nLasst uns sehen, ob wir nicht Hilfe aus dem großen Wald herbeirufen könnten, damit wir zum verbrannten Tal reisen können, bevor es zu spät ist." }, enUS = { completion = "Keeper Albagorm was wise to send you with such urgency.\n\nLet us see if we cannot call forth aid from the great forest to travel to the Charred Vale before it is too late." } })
apply(1060, { "classic", "forever" }, { deDE = { progress = "Ihr scheint mir ein fragwürdiger Charakter zu sein. Wollt Ihr mir etwas zeigen?", completion = "Ah, ein Brief von Darsok. Ich habe seit Jahren nichts mehr von ihm gehört.\n\nDie letzte Blutfeder ist also tot, was? Das sind gute Neuigkeiten. Ich kann mich noch daran erinnern, als mein Freund Rokhan mit diesem verrückten Mok'Nathal auszog, um ihre ältere Schwester zu töten. Ah, könnte man doch noch mal jung sein." }, enUS = { progress = "You seem a shady character. You have something for me to see?", completion = "Ahh, a letter from Darsok. I have not heard from him in many years.\n\nSo the last of the Bloodfeathers are dead, eh? That is good news, I can remember when my friend Rokhan went with that crazy mok'nathal to kill her older sister. Ah, to be young again, like you." } })
apply(1061, { "classic", "forever" }, { deDE = { completion = "Ah, {class}. Sehr gut. Wir werden Eure Fähigkeiten brauchen, um diese Brandschatzer zu bekämpfen!" }, enUS = { completion = "Ah, a {class}.  Very good.  We will need your skills to deal with these plunderers!" } })
apply(1062, { "classic", "forever" }, { deDE = { completion = "Tapfer, tapfer, {name}.\n\nWir werden letztendlich die Weisheit der Taurenältesten benötigen, um die Geister des Steinkrallengebirges zu beschwichtigen, aber...\n\nDer \"Personalabbau\" bei der Venture Company ist schon ein guter Anfang." }, enUS = { completion = "Bravely done, {name}.\n\nWe may ultimately need the wisdom of tauren elders to calm the spirits of Stonetalon, but...\n\nRidding the Venture Company of its personnel is a good first move against them." } })
apply(1063, { "classic", "forever" }, { deDE = { completion = "Ich entbiete Euch meinen Gruß. Seid Ihr wegen eines Rates gekommen?" }, enUS = { completion = "I bid you greetings.  You are here seeking counsel?" } })
apply(1064, { "classic", "forever" }, { deDE = { completion = "Magatha hat mir Euer Kommen angekündigt, {name}. Obwohl mein Herz nicht mehr schlägt, sorge ich mich doch um die Geister des Steinkrallengebirges.\n\nDie Verlassenen brennen darauf, auf jede erdenkliche Weise zu helfen." }, enUS = { completion = "Magatha sent word of your coming, {name}.  Although my heart beats no longer, I still feel sorrow for the spirits of Stonetalon.\n\nThe Forsaken are eager to offer what help we can." } })
apply(1065, { "classic", "forever" }, { deDE = { progress = "Ah, bringt Ihr mir meine neuesten Versuchskaninchen?", completion = "Eine Notiz von Zamah? Es muss dringend sein, wenn sie mir von so weit her eine Nachricht zukommen lässt. Mal sehen, was sie schreibt...\n\nAh, großartig! Ich weiß genau, was zu tun ist!" }, enUS = { progress = "Ah, are you here with my new test subjects?", completion = "A note from Zamah?  Her needs must be great to send word from so far.  Let us see what she says...\n\nAh, splendid!  I know exactly what to do!" } })
apply(1066, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schattenmagier des Syndikats gefunden und von ihnen Blut bekommen?", completion = "Sehr gut! Das Syndikat hat Euch doch hoffentlich nicht allzu viele Schwierigkeiten gemacht?\n\nWie ich erwähnte, kommt man nicht leicht an das Blut Unschuldiger heran. Wir haben Glück, dass die Schattenmagier des Syndikats uns diese schwierige Arbeit abgenommen haben.\n\nWartet bitte einen Moment, während ich mein Gebräu herstelle ..." }, enUS = { progress = "Did you find the Syndicate Shadow Mages, and collect from them the blood?", completion = "Very good!  I trust the Syndicate gave you little trouble?\n\nAs I mentioned, the blood of innocents is not an easy thing to obtain.  We are lucky the Syndicate shadow mages did the difficult work for us.\n\nNow hold a moment while I create my concoction..." } })
apply(1068, { "classic", "forever" }, { deDE = { completion = "Die Zerstörung der Maschinen XT:4 und XT:9 hat viele der Geister des Steinkrallengebirges besänftigt, {name}. Hoffen wir, dass sich die Venture Company aufgrund dieses Verlustes aus diesen Bergen zurückziehen wird.\n\nGeschieht dies nicht, fürchte ich, dass die Gräueltaten, die dieser Ort bereits erleiden musste, nur ein fahler Vorgeschmack auf das sind, was ihm noch bevorsteht." }, enUS = { completion = "The destruction of the machines XT:4 and XT:9 have soothed many of the spirits of Stonetalon, {name}.  With their loss, let us hope the Venture Company will remove itself from these mountains.\n\nFor if they do not, then I fear the atrocities this place has suffered will pale to what lies ahead." } })
apply(1069, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Eier, {name}? Ich habe mit Werftmeister Dizzywig bereits eine Transportvereinbarung getroffen!", completion = "Ihr habt sie! Danke!\n\nIch werde sie Dizzywig schicken, der sie dann nach Booty Bay verschifft. Ich kann den Profit schon fast schmecken!\n\nHier ist Euer Anteil, {name}. Ohne Euch hätte ich dieses Geschäft nicht machen können." }, enUS = { progress = "Did you get the eggs, {name}?  I already made a shipping deal with Wharfmaster Dizzywig!", completion = "You got them!  Thank you!\n\nI'll have these sent to Dizzywig and get them shipped to Booty Bay.  I can already taste the profits!\n\nHere is your cut, {name}.  I couldn't have made this deal without you." } })
apply(1070, { "classic", "forever" }, { deDE = { completion = "Ah, Ihr seid auf Taras Geheiß aus Ashenvale gekommen - wie sehr ich sie vermisse, mein Heimatland und meine Freunde. Sie muss mit ihren Schildwachen sehr beschäftigt sein, wenn sie Abenteurer für andere Aufgaben rekrutieren muss. Ich bin sehr stolz auf sie.\n\nEs ist mir eine Freude, Eure Bekanntschaft zu machen, {name}." }, enUS = { completion = "Ah, you've come from Ashenvale at the behest of Tara--how I miss her, my homeland and friends. She must be doing well with the Sentinels to be sequestering adventurers for other tasks. I'm proud of her.\n\nIt is a pleasure to meet you, {name}." } })
apply(1071, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Schlacht bei Euch, {name}?", completion = "Vielen Dank für Eure Hilfe, {name}. Ihr kommt gerade rechtzeitig zurück.\n\nIch glaube, ich habe den perfekten Plan... Sprengstoff. Nein, das ist noch nicht der Plan, aber ein Teil des Plans.\n\nSeht Ihr, ich habe hochexplosiven Sprengstoff benutzt - keine Sorge, der ist gar nicht so gefährlich, wie alle meinen -, um den Goblins ein bisschen Angst einzujagen. Ich kann sie mit ein paar gezielt platzierten Sprengungen entlang des Gebirgsrandes ziemlich gut zusammentreiben, aber mir gehen langsam die Vorräte aus..." }, enUS = { progress = "How goes the battle on your end, {name}?", completion = "Thanks so much for your help, {name}. You're actually back just in time.\n\nI think I've got a perfect plan... explosives. No, that's not the plan, but it's part of the plan.\n\nSee, I've been using high explosives--don't worry, they're not as dangerous as everyone thinks--to scare the goblins back a bit. I can herd 'em pretty good with a few key detonations along the mountains' edges, but I've been low on supplies now for a few days..." } })
apply(1072, { "classic", "forever" }, { deDE = { completion = "Ahhh... Gaxim hat Euch geschickt? Woher weiß ich, dass Ihr mich nicht belügt? Hmm? Hmm...?" }, enUS = { completion = "Ahhh.... Gaxim sent you, huh? How do I know you're not lying to me?! Hmm? Hmm...?" } })
apply(1074, { "classic", "forever" }, { deDE = { progress = "Ah, prima, prima, Ihr seid zurück.", completion = "Ihr habt Eure Aufgabe fehlerfrei erledigt, {name}.\n\nNG-5 ist die wichtigste Komponente in diesem Rezept zur Zündung der Wagen mit Dynamit.\n\nWas? Ja, Dynamit... ganze Wagenladungen. Das ist das perfekte Ablenkungsmanöver... Ihr werdet es schon sehen." }, enUS = { progress = "Ah, goodie goodie, you're back.", completion = "Your task has been done flawlessly, {name}.\n\nNG-5 is the unequivocal component in the recipe to ignite the wagons of dynamite.\n\nWhat? Yes, dynamite... wagons of it. It's the perfect distraction, I tell you... just wait and see." } })
apply(1075, { "classic", "forever" }, { deDE = { completion = "Tja, dieser Zauber, den Ihr benötigt... einen, mit dem man Sprengstoff aus der Entfernung zünden kann... hmmm." }, enUS = { completion = "Now, this spell you need; one that will allow you detonate explosives from a distance... hmmm." } })
apply(1076, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr die Komponente gefunden, die ich benötige?", completion = "Einen kleinen Moment noch, dann habe ich die Rolle für Euch fertig." }, enUS = { progress = "Hello, {name}. Have you found the component I need?", completion = "Allow me just a few moments and I shall have your scroll ready for you." } })
apply(1077, { "classic", "forever" }, { deDE = { progress = "Haha! Ihr seid zurück! Habt Ihr ihn? Habt Ihr den Zauber?", completion = "Das ist perfekt, {name}. Gut gemacht.\n\nDieser Zauber in Verbindung mit dem NG-5 ergibt einen perfekten Sprengstoff mit Fernzündung.\n\nWir werden eine perfekte Ablenkung für Euch schaffen, damit Ihr hineinschleichen und alle Briefe und Ingenieurspläne der Venture Company stehlen könnt.\n\nDas wird ihre Rodungsaktionen behindern." }, enUS = { progress = "Haha! you're back! Do you have it? Do you have the spell?", completion = "This is perfect, {name}! Well done.\n\nThis spell, mixed with the NG-5, shall make the perfect remote explosive.\n\nWe'll be able to create the perfect distraction for you so you can sneak in and steal the Venture Co.'s letters and engineering plans.\n\nThat will surely slow down their deforestation acts." } })
apply(1078, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}.\n\nSeid Ihr mit den Schuppen schon wieder aus dem Tal im Steinkrallengebirge zurück?", completion = "Das ist perfekt, {name}. Vielen, vielen Dank.\n\nVielleicht kann ich Euch eines Tages einmal so helfen, wie Ihr mir geholfen habt." }, enUS = { progress = "Hello again, {name}.\n\nHave you already returned from the Vale in Stonetalon with those scales?", completion = "This is perfect, {name}. Thank you greatly.\n\nPerhaps one day in the future I'll be able to help you as you have helped me." } })
apply(1079, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Pläne, {name}?", completion = "Einfach erstaunlich! Das versetzt der Venture Company einen Riesenschlag.\n\nJetzt können wir Schwächen an ihren Maschinen aufdecken und ihre Entwürfe für unsere eigenen Kreationen ausnutzen. Das ist heute wahrlich ein Freudentag." }, enUS = { progress = "Did you get the plans, {name}?", completion = "Truly amazing! This is a huge blow to the Venture Co.\n\nWe'll be able to find weaknesses in their machines and also incorporate their designs into our own creations. This is a wonderful day, indeed." } })
apply(1080, { "classic", "forever" }, { deDE = { progress = "Wie ist es gelaufen, {name}?", completion = "Unglaublich, {name}! Kaela und die Schildwachen werden überglücklich sein. Mit Euren Fertigkeiten und meinen Erfindungen sind wir unschlagbar." }, enUS = { progress = "How'd it go, {name}?", completion = "Incredible, {name}! Kaela and the Sentinels will be so happy. With your skill and my creations, we're unstoppable." } })
apply(1081, { "classic", "forever" }, { deDE = { completion = "Hallo, {name}. Ich habe tatsächlich schon von Euch gehört, und obwohl Ihr noch so jung seid, freue ich mich zu sehen, welchen Lebensweg Ihr eingeschlagen habt.\n\nIhr würdet mir eine große Ehre erweisen, wenn Ihr das hier als Zeichen meiner Anerkennung annehmen würdet." }, enUS = { completion = "Hello, {name}. I have indeed heard your name before, and although you are still full of youth, I am pleased to see the path you have set for yourself.\n\nYou would do me a great honor if you would accept this as a gift of appreciation." } })
apply(1082, { "classic", "forever" }, { deDE = { completion = "Danke, {name}. Ihr habt den Schildwachen einen großen Dienst erwiesen.\n\nIch freue mich, dass es Kaela... und auch Gaxim gut geht.\n\nIhr habt Eure Anerkennung verdient." }, enUS = { completion = "Thank you, {name}. You have done a service to the Sentinels.\n\nI'm glad to see Kaela... and even Gaxim, are doing well.\n\nYou've earned our appreciation." } })
apply(1083, { "classic", "forever" }, { deDE = { progress = "Als ich das verbrannte Tal zum ersten Mal sah, hätte ich fast geweint, {name}.", completion = "Die Überreste unseres Feindes... Eure Kraft hat uns gute Dienste geleistet, {name}. Danke." }, enUS = { progress = "The first time I saw the Charred Vale I almost wept, {name}.", completion = "The remains of our enemy... your strength serves us well, {name}. Thank you." } })
apply(1084, { "classic", "forever" }, { deDE = { progress = "Ich habe das Gefühl, Gaxim wird einen Verwendungszweck für den Span finden, ungeachtet dessen, wofür die Venture Company ihn in der Vergangenheit benutzt haben mag.", completion = "Danke, {name}.\n\nDas sollte mehr als ausreichend sein, damit Gaxim herausfinden kann, wie die Treants verderbt wurden. Ich werde ihm das sofort bringen." }, enUS = { progress = "I have a feeling Gaxim will find a use for the shrapnel regardless of how the Venture Co. has used it in the past.", completion = "Thank you, {name}.\n\nThis should be more than sufficient for Gaxim to figure out how the treants were corrupted. I shall give this to him right away." } })
apply(1085, { "classic", "forever" }, { deDE = { completion = "Tückisch... tückisch und gefährlich ist das Land.\n\nAber ich bin hier, um den Nachtelfen zu zeigen, dass es durch die gute alte Ingenieurskunst und einen Tick Magie ein bisschen sicherer werden kann.\n\nWisst Ihr, der Magie total abzuschwören, würde den Nachtelfen nicht helfen - sie brauchen sie. Die Welt braucht sie. Und nimmt man Ingenieurskunst und Alchimie noch dazu, kann nichts mehr schiefgehen. Die Möglichkeiten sind endlos." }, enUS = { completion = "Treacherous... treacherous and dangerous, that's what this land is.\n\nBut I'm here to show the night elves that it's a little safer with the help of good ole engineering and a dash of magic.\n\nSee, swearing off magic completely won't help the night elves--they need it. The world needs it. And with engineering and alchemy to boot, you can't go wrong. The possibilities are endless." } })
apply(1086, { "classic", "forever" }, { deDE = { completion = "Ihr habt den Flugplatz gefunden? Gut gemacht, {name}! Die Goblins waren sicher ziemlich überrascht von Eurer Lieferung! Hoffen wir, dass das Toxin den Weg zu ihrem Hauptquartier findet.\n\nIhr habt Eurem Volk gute Dienste geleistet, und ich rate Euch, dass Ihr Euch nicht mit Schuldgefühlen quält, die Ihr vielleicht wegen der Vergiftung der Venture Company hegt. Sie hat noch viel Schlimmeres verdient.\n\nUnd wenn die Verlassenen ihren Verbündeten noch ein Körnchen Wissen vermitteln können, dann dies hier:\n\nScheut Euch nicht, dunkle Wege zu begehen... wenn Euch solche Wege zum Sieg führen." }, enUS = { completion = "You found the port?  Well done, {name}!  I am sure the goblins were quite surprised from your delivery!  Let us hope that toxin finds its way to their headquarters.\n\nYou have served your people well, and I advise you to ignore any guilt you might harbor for poisoning the Venture Company.  They are deserving of far worse.\n\nAnd if there is one mote of wisdom the Forsaken might teach its allies, it is this:\n\nDo not shy from dark paths... if those paths lead to victory." } })
apply(1087, { "classic", "forever" }, { deDE = { progress = "Kanalisieren von Magie ist, als würde man mit einem löcherigen Eimer Wasser aus einem Brunnen schöpfen.", completion = "Ich kann es bereits spüren... ja... oh süße Macht... die rauschende Flut. Die Kaldorei sind töricht, dass sie die Geschenke dieser Welt verschmähen und das Durchströmen der Magie unterbinden, die singend durch unsere Adern fließt.\n\nWas ist das Leben doch für ein fahler Abklatsch ohne ihre brennende Umarmung!" }, enUS = { progress = "Here, channeling magic is like drawing water from a well with a bucket full of holes.", completion = "Already I can feel it... yes... power so sweet... the rushing flood. The kaldorei are foolish to spurn the gifts of this world, to reject the coursing of magic as it flows singing through your veins.\n\nWhat a pale mockery life is without its burning embrace!" } })
apply(1088, { "classic", "forever" }, { deDE = { progress = "Als mein Meister mich auf den Gipfel des Steinkrallengebirges beorderte, erwartete ich, dass ich einfach nur die Nachtelfen beseitigen musste, die in den heiligen Ruinen unseres antiken Tempels von Azshara herumwimmelten und seine Heiligkeit plünderten... aber Ordanus schlüpfte mir zwischen den Fingern hindurch.", completion = "Ich kannte Ordanus einst, aber das ist schon lange her. Er besaß die Arroganz seiner Art und stellte sich selbst noch über die Hochgeborenen.\n\nJetzt trägt er seinen Kopf nicht mehr so hoch, nicht wahr, {name}?\n\nIch versprach Euch eine Belohnung, und die sollt Ihr haben. Kommt mit mir." }, enUS = { progress = "When my master bade me to the peak of Stonetalon, I expected that all I would need was to lay waste to the night elves that crawled the sacred ruins of our ancient temple of Azshara, their touch despoiling its sanctity... but Ordanus had slipped my grasp.", completion = "I knew Ordanus once, long ago. He had the arrogance of his kind, holding himself above even the Highborne.\n\nHis head does not rise so high now, does it, {name}?\n\nI promised you a reward, and you shall have it. Attend to me." } })
apply(1089, { "classic", "forever" }, { deDE = { progress = "In den Stein sind drei Schlüssellöcher eingearbeitet.", completion = "Als die drei Schlüssel in die jeweiligen Öffnungen gesteckt werden, tauchen inmitten des glimmenden Lichtes ein paar Gegenstände auf." }, enUS = { progress = "Three keyholes are carved into the stone.", completion = "As the three keys are slid into their matching openings, in the middle of the glowing light a number of items appear." } })
apply(1090, { "classic", "forever" }, { deDE = { completion = "Danke, {name}. Sah für einen Moment ziemlich riskant aus und wir haben vielleicht etwas zu viel Aufmerksamkeit auf uns gelenkt.\n\nDas Wichtigste ist aber, dass wir eine Erzprobe haben, die wir so schnell wie möglich zu Ziz bringen sollten." }, enUS = { completion = "Thanks, {name}. It was looking a little dicey there for a second and we've probably drawn far too much attention to ourselves.\n\nThe important part is that we have the ore sample, though, and we should get it to Ziz as soon as possible." } })
apply(1091, { "classic", "forever" }, { deDE = { progress = "Ja, {name}? Was kann ich für Euch tun?", completion = "Das ist in der Tat interessant.\n\nIhr und Gaxim habt das sehr gut gemacht, {name}. Danke." }, enUS = { progress = "Yes, {name}? What can I do for you?", completion = "This is interesting indeed.\n\nYou and Gaxim have done very well, {name}. Thank you." } })
apply(1092, { "classic", "forever" }, { deDE = { progress = "Kann ich Euch irgendwie helfen?", completion = "Ahhh, ich wusste, dass es richtig war, Piznik zu sagen, dass er dort bleiben soll. Die Ingenieure in Undermine werden sich das bestimmt unbedingt ansehen wollen...\n\nNatürlich werde ich ein kleines Stückchen für mich behalten, aber das müssen sie ja nicht unbedingt wissen, was?" }, enUS = { progress = "Something I can help you with?", completion = "Ahhh, I knew that I did the right thing by telling Piznik to stay behind. I'm sure the engineers in Undermine will be most interested to look at this...\n\nOf course I'll want to keep a little piece for myself, but what they don't know won't hurt them, yes?" } })
apply(1093, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Pläne gefunden? Ich brenne darauf, meinen neuen Boss zu beeindrucken. Hoffentlich überzeugt ihn das von meiner Loyalität - soweit man ihn überhaupt überzeugen kann... Goblin-Ehre, Ihr wisst schon. Vielleicht ist er dann geneigt, sich mein ziemlich beeindruckendes Genie zu Nutze zu machen.", completion = "He, ist es das, für was ich es halte? Großartig!\n\nDann sehen wir mal. Ähhh... wie soll denn das jemand verstehen... versteh einer die Denkweise von Gnomen. Ich sag Euch was, ich wundere mich, dass sie Räder bauen können, ganz zu schweigen von diesen Flugapparaten, die sie so sehr lieben." }, enUS = { progress = "Did you find those plans? I'm eager to impress the new boss. Hopefully, once he's convinced of my loyalty--well, as much as he can be convinced... goblin's honor, you know?--he'll feel comfortable making use of my rather impressive genius.", completion = "Hey, is that what I think it is? Great!\n\nNow, let's see. Ugh... how am I supposed to understand this stuff... can't figure out the way gnomes think. Lemme tell you, I'm surprised they could build the wheel, let alone those flying machines they like so much." } })
apply(1094, { "classic", "forever" }, { deDE = { progress = "Hallo! Wie kann ich Euch helfen?", completion = "Fizziks, hä? Kann nicht sagen, dass ich ihm traue, aber diese Informationen scheinen ganz brauchbar. Was würde ich darum geben, die Venture Company endlich los zu sein.\n\nDie haben sich allerdings ein paar recht gute Maschinen ausgedacht... Ich kann nicht bestreiten, dass wir von ein paar Verbesserungen, die sie entwickelt haben, ganz gut profitiert haben." }, enUS = { progress = "Hello there! How can I help you?", completion = "Fizziks, eh? Can't say I trust him, but this information seems good enough. What I wouldn't give to have the Venture Company out of my hair.\n\nThey do come up with some good machines though... I can't deny that we've benefited from using some of the improvements they've devised." } })
apply(1095, { "classic", "forever" }, { deDE = { completion = "Gerenzo eliminieren? Also das ist eine Sache, gegen die ich nichts einzuwenden habe.\n\nGnome an sich sind ja schon schlimm genug, aber was ich alles über Gerenzo gehört habe, schlägt dem Fass den Boden aus. Offenbar war er einer der leitenden Ingenieure in Gnomeregan, wo er an einem Geheimprojekt mitwirkte - wir konnten Dun Morogh nie gut genug infiltrieren, um genauere Einzelheiten darüber herauszufinden. Es war ein Fehlschlag. Unseren Berichten nach soll das, was immer es auch war, ihnen buchstäblich um die Ohren geflogen sein." }, enUS = { completion = "Eliminate Gerenzo? Now there is a prospect that I have no objections to.\n\nGnomes are bad enough as it is, but what I learned about Gerenzo only makes it worse. Apparently, he was one of the head engineers in Gnomeregan, where he was working on their secret project--we could never infiltrate Dun Morogh well enough to find out specific details. It was a failure. Our reports say that whatever it was literally exploded in their faces." } })
apply(1096, { "classic", "forever" }, { deDE = { progress = "Sputtervalve wird einen Beweis für Gerenzos Tod haben wollen. Ich glaube, dieser mechanische Arm wird reichen.", completion = "Man sehe sich dieses Ding an... so was kann sich auch nur ein Gnom ausdenken. Ich kann nicht verstehen, warum man sich einen Arm abschneidet und durch so was ersetzt, wenn man doch beide Arme behalten und einfach einen dritten ansetzen könnte!\n\nGnome, ich sag's Euch...\n\nZumindest ist Gerenzo jetzt außer Gefecht. Hoffentlich ist das Beweis genug und Sputtervalve bringt mich in einer der Tüftlerverband-Werkstätten in Gadgetzan oder sogar Undermine unter." }, enUS = { progress = "Sputtervalve will want some sort of proof that Gerenzo's dead. I think his mechanical arm will probably do.", completion = "Look at that thing... it'd take a gnome to come up with something like that. I can't understand why you'd cut off an arm, and replace it with that, when you could just keep both arms and add a third!\n\nGnomes, I tell you...\n\nAt least Gerenzo's out of commission. Hopefully that'll be enough proof, and Sputtervalve will assign me to one of the Tinkers' Union workshops in Gadgetzan or maybe even Undermine." } })
apply(1097, { "classic", "forever" }, { deDE = { completion = "Ihr seid hier, um mir mit meiner Lieferung zu helfen? Sehr gut!" }, enUS = { completion = "You're here to help with my delivery?  Very good!" } })
apply(1098, { "classic", "forever" }, { deDE = { completion = "Vincents Körper liegt zerschmettert und leblos da.\n\nTodespirscher Adamant wird Hadrec zwar seinen Bericht schicken... aber was immer Vincent zusätzlich noch wusste, wird für immer sein Geheimnis bleiben.\n\nSeine Hand jedoch umklammert ein kleines Stück Plunder..." }, enUS = { completion = "Vincent's body lies broken, and still.\n\nAlthough Deathstalker Adamant will send his report to Hadrec... whatever additional details Vincent gained must remain with him.\n\nBut clutched in his hand is a small trinket..." } })
apply(1100, { "classic", "forever" }, { deDE = { progress = "So bekümmert, wie Ihr ausseht, würde ich sagen, dass etwas nicht stimmt...", completion = "Ihr sagt, Ihr habt das Tagebuch bei einem verstorbenen Zwerg gefunden? Gebt mir einen Moment Zeit, um durch die Seiten zu stöbern..." }, enUS = { progress = "From your look of concern, I can tell that something is amiss....", completion = "You say you found this journal on a deceased dwarf? Give me but a moment to peruse the pages..." } })
apply(1101, { "classic", "forever" }, { deDE = { progress = "Solange Charlga Razorflank im Kral von Razorfen Truppen rekrutiert, ist dieses Land in großer Gefahr.", completion = "Der Greisin wurde der Garaus gemacht. Das sind phantastische Neuigkeiten, {name}.\n\nIn diesen gefährlichen Zeiten ist es erfrischend, jemanden zu sehen, der so mutig ist wie Ihr.\n\nDa Razorflanks Diener beseitigt sind, können wir jetzt unsere Studien in diesem Gebiet fortsetzen. Vielleicht erfahren wir ja jetzt mehr darüber, was die Ruhestätte Agammagans verderbt hat.\n\nIch fürchte allerdings, dass die Antwort auf diese Frage auch mit Verrat zu tun hat ..." }, enUS = { progress = "So long as Charlga Razorflank is mustering a force in Razorfen Kraul, these lands are in great danger.", completion = "The crone has been laid to rest. This is fantastic news, {name}.\n\nIn these times of peril, it is refreshing to see one as brave as yourself.\n\nWith Razorflank's minions taken care of, our studies in the area can continue. Perhaps now we can gain further knowledge of exactly what happened to corrupt the resting place of Agamaggan.\n\nHowever, I fear the answer to that question lies in treachery as well..." } })
apply(1102, { "classic", "forever" }, { deDE = { progress = "Sobald ich weiß, dass die elenden Bestien des Krals von Razorfen aus ihrem elenden Unterschlupf vertrieben wurden, kann ich in Frieden ruhen, in dem Wissen, dass Rache geübt wurde. \n\nHabt Ihr die Stacheleber aus dem Kral vertrieben? Bringt Ihr mir gute Neuigkeiten in Form von Razorflanks Herz?", completion = "Wie ich sehe, kennt der widerliche Stamm des Krals von Razorfen jetzt den Schmerz meines Volkes. Das geschieht den elenden Bestien recht.\n\nJemanden von heiligem Boden zu vertreiben ist eine Sünde, die nur durch die schlimmste Form der Rache gesühnt werden kann.\n\nDanke, {name}, dass Ihr mir in diesen Zeiten der Not geholfen habt." }, enUS = { progress = "Once I know the foul beasts of Razorfen Kraul have been driven from their foul lair, I will be able to rest in peace, knowing that revenge has been served.\n\nHave you the driven the quilboar from the Kraul? Do you bring to me good news in the form of Razorflank's heart?", completion = "I see the nasty tribe of Razorfen Kraul now knows the pain of my people. Serves the foul beasts right.\n\nTo drive one from a holy land is a sin worthy of the most severe revenge.\n\nThank you, {name}, for aiding me in my plight." } })
apply(1104, { "classic", "forever" }, { deDE = { progress = "Hi, hi, hi! Habt Ihr das Gift???", completion = "Toll! Dieses Gift wird wunderbar funktionieren! Danke, {name}!\n\nJetzt muss ich ihn nur noch einkochen lassen, Skipper-Otomer und einen Nagakatalysator hinzufügen, und... Mist! Wo sind meine Notizen?!" }, enUS = { progress = "Hi hi hi!  Did you get that venom??", completion = "All right!  This venom is going to work great!  Thanks, {name}!\n\nNow I just need to boil it down, apply skipper-otomer, add a nega-catalyst, and... Drat!  Where are my notes!?" } })
apply(1105, { "classic", "forever" }, { deDE = { progress = "Mein Bruder macht Fortschritte mit seinem neuen Treibstoff, und das macht mir Sorgen. Ich muss so bald wie möglich mit meiner Arbeit mit einem Schildkrötenpanzer-Treibstofftank beginnen!\n\nHabt Ihr die Panzer schon, {name}?", completion = "Ihr habt sie! Danke, {name}!\n\nWow, diese Panzer sind härter als ich dachte! He, ich ruiniere mir bestimmt einen ganzen Kasten voller Werkzeuge, wenn ich daran arbeite!" }, enUS = { progress = "My brother is making progress with his new fuel design, and that has me worried.  I need to start work on a tortoise shell fuel tank as soon as possible!\n\n{name}, do you have those shells yet?", completion = "You got them!  Thanks, {name}!\n\nWow, these shells are harder than I thought!  Heh, when I work with them I'll probably bend a whole box full of tools!" } })
apply(1106, { "classic", "forever" }, { deDE = { progress = "Tja, da habt Ihr mich also gefunden. Schön für Euch.\n\nSeid Ihr wegen der Axt hier, die ich für Gath'Ilzogg geschmiedet habe? Oder seid Ihr hier, um die Ehre der Herzogin Pamay zurückzufordern?\n\nWisst Ihr, es ist mir völlig egal, warum Ihr hier seid. Wenn Ihr hier seid um zu kämpfen, dann bringen wir's hinter uns ...", completion = "Fizzle hat Euch geschickt? Also das ändert die Sachlage! Natürlich helfe ich Euch. Fizzle und sein Bruder sind zwei der wenigen Leute, die mich nicht tot sehen wollen!\n\nFizzle will also Kolben herstellen, was? Kolben, die stark genug sind, um großen Belastungen standhalten zu können; was auch immer ihm vorschweben mag. Und wie ich Fizzle kenne, wird sein neuer Wagen ein Vulkan auf Rädern!" }, enUS = { progress = "Well, you found me.  Good for you.\n\nAre you here about that axe I made for Gath'Ilzogg?  Or are you here to reclaim Duchess Pamay's honor?\n\nActually, I don't care which it is.  If you're here to fight, then let's get it over with...", completion = "Fizzle sent you?  Well that changes things!  Of course I'll help you.  Fizzle and his brother are two of the few people who don't want me dead!\n\nSo Fizzle wants to make pistons, eh?  Pistons strong enough to take whatever stresses he has planned, and if I know Fizzle, then this new car of his is a volcano on wheels!" } })
apply(1107, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schwanzflossen? Wenn ich unseren Wagen nicht vor seinem eigenen Tempo schützen kann, wird er bei den Rennen nicht lang halten.", completion = "Danke, {name}! Wenn ich die zermahlen und mit ein paar anderen Zutaten vermischt habe, ist mein Stoff fertig. Danach wird der Wagen vor seinem eigenen Tempo sicher sein.\n\nSofern er nicht mit irgendwas zusammenstößt..." }, enUS = { progress = "Do you have the tail fins?  If I can't protect our car from its own speed, then it won't last long in these races.", completion = "Thank you, {name}!  After I grind these down and fuse them with a few other ingredients, the composite will be ready.  And after that, the car will be safe from its own speed.\n\nSafe, as long as it doesn't hit anything..." } })
apply(1108, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Induriumspäne gefunden, {name}? Meine Schmiede ist aufgeheizt und bereit, sie zu testen.", completion = "Ah ja, ausgezeichnet. Geben wir sie ins Feuer und sehen wir, wie sie sich machen..." }, enUS = { progress = "Did you find any indurium flakes, {name}.  I have my forge heated up and ready to test them.", completion = "Ah yes, these will do fine.  Now let's put them in some heat and see how they fare..." } })
apply(1109, { "classic", "forever" }, { deDE = { progress = "Ah, wie ich sehe, seid Ihr zurückgekehrt. Konntet Ihr etwas Kral-Guano beschaffen?", completion = "Ausgezeichnet! Das ist genau das, was wir brauchen, {name}." }, enUS = { progress = "Ah, I see you have returned. Were you able to procure any Kraul Guano?", completion = "Splendid! This is just the start we needed, {name}." } })
apply(1110, { "classic", "forever" }, { deDE = { progress = "{name}, seid Ihr in der Ebene gewesen? Habt Ihr mir die Ladung Teile gebracht, die ich wollte?", completion = "Boah, seh sich einer das an! Es sind ein paar echt gute Sächelchen in diesem Schrotthaufen. Ich bin sicher, die kann ich für ein schönes Sümmchen verpfänden.\n\nUnd... sehe ich da ein zerquetschtes Ohr zwischen zwei Metallteilen??? Autsch! He, mit diesem Piloten möchte ich echt nicht tauschen!\n\nDanke, {name}. Hier ist Eure Bezahlung. Und hier noch ein kostenloser Rat...\n\nWenn man verbissen genug sucht, kann man immer Kapital aus der Tragödie eines anderen schlagen." }, enUS = { progress = "{name}, have you been out into the Flats?  Did you bring back that load of parts I wanted?", completion = "Whoa, look at all that!  There's some good stuff in that heap of junk.  I'm sure I can pawn it off for a hefty sum.\n\nAnd... is that an ear I see squashed between those two sheets of metal??  Ouch!  Heh, I sure wouldn't want to be that pilot!\n\nThanks, {name}.  Here's your pay.  And here's some advice, free of charge...\n\nIf you look hard enough, you can always find profit in someone else's tragedy." } })
apply(1111, { "classic", "forever" }, { deDE = { progress = "Sprecht! Sagt mir, ladet Ihr aus oder ein?", completion = "Oh, ja. Teile für Kravel. Schön, dass Ihr hier seid. Diese Dinger liegen seit Tagen hier, ich fürchtete schon, sie würden Rost ansetzen." }, enUS = { progress = "Speak up!  Tell me, are you dropping off or picking up?", completion = "Oh yes.  Parts for Kravel.  I'm glad you're here.  These things have been sitting out here for days, and I was afraid they'd rust!" } })
apply(1112, { "classic", "forever" }, { deDE = { progress = "Seid Ihr in Ratchet gewesen und habt die Teile bekommen?", completion = "Prima, Ihr habt sie! Jetzt müssen wir sie zu den Gnomen bringen. Aber vorher...\n\nNehmen wir einen kleinen Gegenstand heraus..." }, enUS = { progress = "Did you make it to Ratchet and get those parts?", completion = "Great, you got them!  Now we need to get them to the gnomes.  But first...\n\nLet's take out one small item..." } })
apply(1113, { "classic", "forever" }, { deDE = { progress = "Seid Ihr vom Scharlachroten Kloster zurückgekehrt? Ich brauche viele Herzen für dieses aufregende Experiment!\n\nZweifellos werden Varimathras und die dunkle Fürstin ebenfalls erfreut sein, den Scharlachroten Abschaum loszuwerden...", completion = "Was für eine Unmenge an Gekröse Ihr mir da bringt, {name}! Eure Bemühungen waren exzellent!" }, enUS = { progress = "Have you returned from the Scarlet Monastery? I'll need many hearts for this delightful experiment!\n\nNo doubt, Varimathras and the Dark Lady will be pleased to be rid of the Scarlet Scum as well...", completion = "My what an abundance of gore you have brought me, {name}! Your efforts have been most excellent!" } })
apply(1114, { "classic", "forever" }, { deDE = { progress = "Habt Ihr denn etwas für mich? Großartig! Lasst sehen!", completion = "Da sind sie ja! Meine Hydro-Ratschen und Repetierbolzen! Diese genügen voll und ganz. Danke!" }, enUS = { progress = "You have something for me?  That's great!  let's see it!", completion = "There they are!  My hydro ratchets and repeater bolts!  These will do just fine.  Thank you!" } })
apply(1115, { "classic", "forever" }, { deDE = { completion = "Ihr wollt etwas über Nazz Steamboil wissen? Er ist Rennfahrer draußen in der schimmernden Ebene, nicht?\n\nKlar kann ich über den was rauskriegen... aber leicht wird das nicht. Und es dauert.\n\nUnd kostet." }, enUS = { completion = "You want to know about Nazz Steamboil?  He's a racer pilot out in the Shimmering Flats, isn't he?\n\nYeah, I might be able to find something out about him... but it won't be easy.  Or fast.\n\nOr cheap." } })
apply(1116, { "classic", "forever" }, { deDE = { progress = "Schon wieder hier? Habt Ihr meinen Traumstaub?", completion = "Seht Euch das an. Ihr habt den Traumstaub gefunden!\n\nUnd Wie hat Euch der Sumpf gefallen, {name}? Ist nicht leicht, dort eine warme Mahlzeit zu bekommen, hm?" }, enUS = { progress = "Back so soon?  Do you have my dream dust?", completion = "Well, look at that.  You found the dream dust!\n\nAnd how did you like the swamp, {name}?  It's not easy to get a hot meal there, is it?" } })
apply(1117, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas über Nazz Steamboil? Etwas, das er unbedingt geheim halten möchte?", completion = "Ach nein! Das ist interessant... sehr interessant. He, vielleicht sollte ich mich vor dem Goblin-Rennfahrer verneigen, wenn ich ihn das nächste Mal sehe.\n\nDas ist eine Menge wert, {name}. Nazz wird ganz bestimmt ein kleines Vermögen bezahlen, damit dieses Geheimnis... ein Geheimnis bleibt." }, enUS = { progress = "Did you get anything on Nazz Steamboil?  Anything he might want to keep a secret??", completion = "Well well!  This is interesting... very interesting.  Heh, perhaps I should bow to the goblin pilot the next time I see him.\n\nThis is worth plenty, {name}.  I'm sure Nazz will pay a small fortune to keep his secret... a secret." } })
apply(1118, { "classic", "forever" }, { deDE = { progress = "Hallo, hallo. Und was führt einen so edlen Eurer Art nach Booty Bay, {race}?", completion = "Verstehe. Kravel hat einen großen Plan in petto. Er ist ein finsterer Schurke - das mag ich an ihm.\n\nIhr braucht also etwas, das den Geist verwirrt, hm? Etwas Mächtiges...\n\nOb man die Mixtur nehmen könnte, die Zanzil seinen Zombies gibt..." }, enUS = { progress = "Hello hello.  And what brings a noble {race} such as you down to Booty Bay?", completion = "I see.  Kravel has a big scheme planned.  He has a sinister mind -- I like that about him.\n\nSo you'll need something to addle wits, eh?  Something powerful...\n\nI wonder if the mixture Zanzil feeds his zombies could be used..." } })
apply(1119, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Konnte Fizzlebub uns helfen?", completion = "Großartig! Fizzlebub kam durch! Ich werde daran denken, wenn ich ihn wiedersehe.\n\nUnd habt Dank, {name}. Ihr macht Eure Sache großartig und wir werden beide eine Menge Geld damit verdienen..." }, enUS = { progress = "Hello, {name}.  Was Fizzlebub able to help us?", completion = "Wonderful!  Fizzlebub came through!  I'll remember that next time I see him.\n\nAnd thank you, {name}.  You're doing a great job, and we both stand to make a lot of money from this..." } })
apply(1120, { "classic", "forever" }, { deDE = { progress = "Hallo! Habt Ihr denn etwas für mich?", completion = "Starkbier? Wie aufmerksam! Danke!\n\nWir sollten nicht trinken, da das Rennen bevorsteht, aber... vielleicht können meine Jungs einen Schluck vertragen. Außerdem kann es ja so stark nicht sein, oder?" }, enUS = { progress = "Hi!  You have something for me?", completion = "Stout?  How considerate!  Thank you!\n\nWe shouldn't be drinking with the race coming up, but... maybe my boys could do with just a little.  Besides, it can't be that strong, can it?" } })
apply(1121, { "classic", "forever" }, { deDE = { progress = "Was glotzt Ihr denn so?", completion = "Was haben wir denn da? Fusel, hm?\n\nAlso mich stört es nicht, wenn wir ein klein wenig..." }, enUS = { progress = "What are you looking at?", completion = "What do we have here?  Booze, eh?\n\nWell, I don't mind if we have just a little..." } })
apply(1122, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Wie hat das Starkbier gewirkt? Starkes Gesöff, was?", completion = "Hier steht, Fools Starkbier war ein Erfolg. Das sind gute Neuigkeiten!\n\nWenn Ihr mehr von dem Zeug wollt, lasst es mich wissen und Ihr könnt mehr von Zanzils Mixtur sammeln." }, enUS = { progress = "Hello {name}.  How'd that stout work out?  It's strong stuff, isn't it?", completion = "It says here that the fool's stout was a success.  That's good news!\n\nIf you ever want more of the stuff, then let me know and I'll have you gather more of Zanzil's Mixture." } })
apply(1123, { "classic", "forever" }, { deDE = { completion = "Ich bin Rabine Saturna und heiße Euch im Namen von Bewahrer Remulos und allen Bewohnern dieses hochheiligen Tales aufs Herzlichste willkommen.\n\nIch weiß Euer Interesse und Euren Eifer bei der Unterstützung des Zirkels des Cenarius zu schätzen. Die Tauren haben eine unglaubliche Neigung für die Lehren des Cenarius gezeigt, und als Vertreter der Horde seid Ihr in der Sicherheit dieses Tales willkommen. Die Erhaltung Azeroths ist ein gemeinsames Ziel, das wir beide verfolgen.\n\nIhr seid hier unter Freunden, {name}." }, enUS = { completion = "I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.\n\nI appreciate your interest and eagerness to assist the Cenarion Circle.  The tauren have shown an incredible propensity to the tenets of Cenarius, and by their proxy the Horde is welcomed within the safety of this glade.  The preservation of Azeroth is a common goal we both share.\n\nYou are among friends here, {name}." } })
apply(1124, { "classic", "forever" }, { deDE = { progress = "Das hier ist ein zu gefährliches Land, um hier so sorglos herumzuwandern, {class}. Was führt Euch in die Ödnis von Silithus?", completion = "Rabine schickt Euch also? Tja, dann betrachtet Euch als willkommen... soweit dieses desolate und verlassene Land jemanden willkommen heißen kann.\n\nDamals, als das große Leiden das Land hier beherrschte, war ich noch nicht geboren, aber es gibt Orte in dieser Wüste, die als unheimliches Anschauungsmaterial dieser vergessenen Zeit dienen könnten. Mit Eurer Hilfe könnte es dem Zirkel des Cenarius gelingen, der Gefahr ein für alle Male ein Ende zu bereiten, einer Gefahr, die angeblich schon vor Generationen ausgerottet sein sollte." }, enUS = { progress = "This is a dangerous land to be so casual, {class}.  What brings you to the wastes of Silithus?", completion = "Rabine sent you, did he?  Well, consider yourself welcomed here... as much as this desolate and forsaken land can welcome someone.\n\nI wasn't alive during the time of the great tribulations that took place here, but there are parts of this desert that might as well be eerie pictures of that forgotten past.  With your help, the Cenarion Circle might be able to bring finality to a threat that was supposed to have died generations ago." } })
apply(1125, { "classic", "forever" }, { deDE = { completion = "Ich hatte mir schon gedacht, dass dieser riesige quirlige Schwarmbau nahe den Ruinen des Dorfes irgendetwas mit seinem Untergang zu tun hat. Mir scheint, dass Euer Wirken das bestätigt hat. Die unmittelbare Nähe des Schwarmbaus stellt eine Bedrohung für unsere zukünftige Arbeit hier dar.\n\nIch danke Euch für Eure Güte, die Seelen der Gefallenen zu befreien. Das ist keine leichte Arbeit, ich weiß. Wenn Ihr bereit seid, würde ich Euch jedoch gern noch einmal um Eure Unterstützung bitten ..." }, enUS = { completion = "I had thought that maybe the huge swirling hive near the ruins of the village had played a part in its demise.  It would seem that your work has proven this to be correct; the proximity of the hive poses a threat to any future work we may do here.\n\nI thank you for your benevolence in freeing the souls of the fallen; such work is never easy, I know.  When you're ready, however, I'd like to ask for your assistance once more..." } })
apply(1126, { "classic", "forever" }, { deDE = { progress = "Na, hat es geklappt? Zumindest seid Ihr noch in einem Stück, und das ist gut. Habt Ihr etwas gefunden?", completion = "Was zum... was ist das?\n\nEs hat die Form eines... Kastens...? Total verkrustet. Wartet, da ist eine freie Stelle... ist das etwa ein Buch unter all diesem Dreck?\n\nIch glaube, Ihr habt da einen außergewöhnlichen Fund gemacht, {name}... zumindest hoffe ich das. Vielleicht ist das ein Tage- oder Logbuch aus alter Zeit, konserviert in dieser Hülle.\n\nIch glaube, ich weiß wie wir herausfinden können was es ist." }, enUS = { progress = "Well, did it work?  You're still in one piece, which is good news.  Did you find anything?", completion = "What the... what is it?\n\nIt has the shape of a... box, maybe?  It's encrusted over something fierce.  Wait, there's a portion here that's exposed... is that a book underneath all this gunk?\n\nI think you've stumbled across quite the find here, {name}... well, at least I hope it is.  Perhaps it is a journal or a log from ancient times, preserved in this shell.\n\nI think I know a way to find out what this is." } })
apply(1130, { "classic", "forever" }, { deDE = { completion = "So, {name}, Ihr seid also gekommen. Seid Ihr denn bereit, eine Reise durch ferne Länder zu beginnen?\n\nWenn ja, {class}, dann hört zu..." }, enUS = { completion = "So, {name}, you have come.  Now, are you prepared to journey through distant lands?\n\nIf so, young {class}, then listen on..." } })
apply(1131, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die elende Stahlbiss besiegt, {name}?", completion = "Durch den Sieg über Stahlbiss habt Ihr Tausend Nadeln von einer schrecklichen Besudelung gesäubert.\n\nUnd das, {name}, ist Eure Lektion für den heutigen Tag." }, enUS = { progress = "Have you defeated the foul Steelsnap, {name}?", completion = "In defeating the creature Steelsnap, you have cleansed the Thousand Needles of a horrible taint.\n\nAnd that, {name}, is your lesson this day." } })
apply(1132, { "classic", "forever" }, { deDE = { completion = "Guten Tag auch! Mr. Flint im Hafen von Menethil hat Euch geschickt? Mr. Flint besitzt eine gute Charakterkenntnis. Wenn er Euch hergeschickt hat, dann gehört Ihr zweifellos nach Kalimdor!" }, enUS = { completion = "Good day to you!  You were sent by Mr. Flint in Menethil Harbor?  Well Mr. Flint is a strong judge of character.  If he sent you, then there's no doubt you belong here in Kalimdor!" } })
apply(1133, { "classic", "forever" }, { deDE = { completion = "Seid Ihr hier, um der Allianz Eure Dienste anzubieten, {name}? Wir sind dankbar für die Unterstützung, denn wiewohl seine Schönheit ungebrochen ist... ist Ashenvale nicht mehr so friedlich wie einst." }, enUS = { completion = "You are here to offer your services to the Alliance, {name}?  We welcome the aid, for although its beauty remains... Ashenvale Forest is not the peaceful place it once was." } })
apply(1134, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Prachtschwingengiftbeutel, {name}. Wir dürfen nicht zulassen, dass die Orcs die Gifte der Bestien gegen uns verwenden!", completion = "Danke, {name}. Es stimmt mich traurig, Kreaturen abschlachten zu lassen, die unsere Feinde nicht freiwillig unterstützen, und doch ist es meine Pflicht.\n\nEuer Herz mag um die Prachtschwingen trauern, die Ihr abschlachten musstet, aber es dürfte Euch mit Freude erfüllen, dass Eure Verbündeten jetzt vor dem Gift der Prachtschwingen sicher sind." }, enUS = { progress = "Do you have the pridewing venom sacs, {name}?  We cannot allow the orcs to use the beasts' poisons against us!", completion = "Thank you, {name}.  It saddens me to order the slaughter of creatures who may not willingly aid our enemies, yet it is my duty to do so.\n\nYour heart might weep for the pridewings you slew, my friend, but may your heart then swell in knowing that your allies are safe from the pridewings' venom." } })
apply(1135, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Steilhang gefunden, {name}? Und Glück bei den Flügeldrachen dort gehabt?", completion = "Ah, die meisten platzen förmlich vor Gift, {name}. Man findet sie normalerweise nur bei jungen Flügeldrachen oder fruchtbaren Weibchen. Das muss ein Gemetzel oben am Steilhang gewesen sein!" }, enUS = { progress = "Did you find Highperch, {name}?  Any luck with the wyverns there?", completion = "Ah, most of these are nearly bursting with venom, {name}.  Such are normally only gathered from young wyverns, or fertile females.  It must have been quite a slaughter up there in Highperch!" } })
apply(1136, { "classic", "forever" }, { deDE = { progress = "Seid Ihr im Alteracgebirge gewesen, {name}? Habt Ihr den scheuen Frostrachen gefunden?", completion = "Kraft und List waren erforderlich, um Frostrachen zu besiegen, {name}.\n\nEuer Weg führte Euch zu den Tälern von Tausend Nadeln und den hohen Bergen von Alterac. Eines Tages wird er Euch durch alle Länder der Erdenmutter führen, denn das ist das Leben des Jägers." }, enUS = { progress = "Have you been to the Alterac Mountains, {name}?  Did you face the elusive Frostmaw?", completion = "Both strength and cunning were needed to find and defeat Frostmaw, {name}.  You have both.\n\nYour path has taken you to the valleys of Thousand Needles and to the high mountains of Alterac.  It will one day lead you through all the Earthmother's lands, for such is the way of the hunter." } })
apply(1137, { "classic", "forever" }, { deDE = { completion = "{name}, Ihr seid zurück! Habt Ihr Martek gefunden? Ihr habt mit ihm gesprochen? Was hat er gesagt? Kann er helfen???\n\nSagt es mir, sagt es mir, sagt es mir!!!" }, enUS = { completion = "{name}, you're back!  You found Martek?  You spoke with him?  What did he say?  Can he help??\n\nTell me, tell me, tell me!!" } })
